import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAO: [CaseTemplate] = [vendingMachinePry, busDriverYell, junkyardTires, deerStandTrespass, flagTheft, borrowedTruck, donationBox, skateboardRefuse, fireAlarmPull, dryerClothes, softballFieldFight, ticketScalper, cameraSmash, rideshareRunner, wheelBootCut, noonBurglary, bankNoteRobbery, cocaineBagStop, sellPillsAtWork, domesticChoke, phoneSnatch, payrollCheckForge, dopeHouseTrailer, atvTheft, deputyShove, pistolFromTruck, trafficCocaineMotel, deliveryRobbery]

    static let vendingMachinePry = SmallCases.make(
        key: "story.vendingMachinePry",
        category: .property,
        headlines: ["Man Caught Prying Open Vending Machine Behind Car Wash", "Vending Company Says $640 in Damage"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a vending machine, causing damage of $640, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "A vending company owner found the coin box of a drink machine behind a car wash pried open on {DATE}. A camera showed a man with a crowbar. {D} was stopped nearby with $38 in quarters and a crowbar in the truck. {DL} says {D.he} found the quarters in a parking lot.",
        state: [E(.video, 3, "Car Wash Camera", "A man in a cap pries the coin box with a crowbar at 11:50 p.m."), E(.physical, 2, "Quarters and Crowbar", "$38 in quarters and a crowbar in {D}'s truck.", .search)],
        defense: [E(.statement, 1, "Found Change", "{DL} says the quarters were from his laundry money.")],
        role: "Vending company owner",
        exam: [.direct("What did you find at the drink machine behind the car wash?", "\"The coin box had been pried open and the door lock broken. The damage to the box and lock came to $640, and the machine was out of service.\""), .direct("How much money was inside when it was opened?", "\"There was about $60 in change in the box when I last emptied it. I keep a route record, so I know roughly what a machine holds.\""), .direct("What does your camera show?", "\"A person with a crowbar working at the coin box after dark. The face is not visible, but the crowbar and the motion are easy to see.\""), .direct("How does the coin box open normally, and what was different that night?", "\"It opens with a key at the front. That night the lock was intact but the box had been bent open at the seam with a prying tool, which left fresh scratches in the paint.\""), .direct("What damage did you document?", "\"The coin box door was bent beyond repair, and the machine needed a new lock set and a repaint. The total cost to repair was about $640.\""), .direct("How is the machine's money collected, and when had you last emptied it?", "\"I collect on Fridays. I emptied it the Friday before, and at the time of the theft there should have been about $60 in change.\""), .cross("Nobody saw {D} at the machine, did they?", "\"No one saw anyone in person. The camera shows a figure, but it does not show a face, so I cannot tell you who it is.\""), .cross("Quarters are common. Why does $38 in quarters point to the defendant?", "\"It does not point on its own. It was part of what the deputy found, along with the crowbar, and the amount fit what was missing.\""), .cross("Is the machine located close to where people live and do laundry?", "\"There are apartments nearby, and plenty of people pass that lot. I can't say who among them was there that night.\""), .cross("What time does the camera show the figure at the machine?", "\"A few minutes after midnight, for about two minutes. Then the figure walks out of view.\""), .cross("Could the $38 in quarters found with the defendant have come from some other source?", "\"Possibly. Quarters are common, and I cannot say that any particular quarter came from my machine.\"")],
        theory: ("{D} pried open a vending machine for the change.", "A man with laundry quarters and a crowbar for his truck."),
        allocution: "\"I was short on money that month, and I'm not proud of that. The quarters in my truck came from my laundry jar and the change I keep for my own apartment machines. The crowbar rides in the truck bed for work. I'm sorry the owner had a damaged machine, and I'll pay what the court says is fair.\"",
        truths: ("{DL}'s phone held a photo of the machine with 'easy money.'", "The crowbar had been in the truck bed for a year, a coworker said."),
        defendant: [.direct("Where did you get $38 in quarters?", "\"Mostly from doing laundry and from change I keep for the machines at my apartment. I keep a jar and I had just emptied it.\""), .direct("Why was a crowbar in your truck?", "\"I use it for work. It rides in the truck bed with other tools, and it had been there for a long time before that night.\""), .direct("Did you pry open that vending machine?", "\"No. I have never touched that machine except to buy a drink. I live close by and drive past that car wash all the time.\""), .direct("How often do you do laundry, and where?", "\"About once a week at the laundromat near my apartment. I collect quarters in a jar and bring them to the machines.\""), .direct("Why were you driving near the car wash at midnight?", "\"I was coming home from a shift and taking a back road I use most nights. I did not stop at the car wash.\""), .direct("What happened when the deputy stopped you?", "\"I pulled over, showed my license, and answered questions. The deputy asked about the crowbar and quarters, and I explained what each was for.\""), .cross("You were stopped near the car wash with a crowbar and a pocket of quarters, weren't you?", "\"Yes, and I realize how it looks. But I live a few blocks away, so being there is not unusual for me.\""), .cross("Why would a person carry that many quarters around in the truck?", "\"It is laundry money. I do not like running out at the laundromat, so I keep extra, and I can show you the jar.\""), .cross("Has your crowbar been used to pry anything recently?", "\"It gets used on work jobs, so yes, it has been used. But not on a vending machine, and not that night.\""), .cross("The camera shows a crowbar being used on the machine at 11:50. You were stopped with a crowbar at 12:10, twenty minutes later. How do you explain that?", "\"I carry that crowbar for work and it's in my truck every day. It looks bad, but twenty minutes can be a long drive and a lot of people carry one.\""), .cross("Why didn't you tell the deputy where your quarters came from the first time you were asked?", "\"I did tell the deputy. I said it was laundry money and the jar was in the truck, and I offered to show the jar.\"")],
        openings: ("Behind a car wash, a vending machine's coin box was pried open, causing $640 in damage. A camera shows a person with a crowbar, and deputies later found {D} nearby with a crowbar in the truck and $38 in quarters.", "{D} carries a crowbar for work and a jar of quarters for laundry. The defense will show that the camera caught no face and that nothing ties {DL} to that machine."),
        closings: ("Pry marks, a camera showing a crowbar, and then {D} found near the scene with a crowbar and a pocket of quarters. These pieces fit together too neatly to be coincidence.", "There is no face on that video and no witness. A work crowbar and laundry quarters in a truck belong to millions of people. The State is asking you to guess, and guessing is not proof."),
        timeline: [(0, "11:50 p.m.: the coin box is pried."), (1, "12:10 a.m.: a deputy stops {DL} nearby."), (1, "The owner finds the damage.")],
        identified: "The car wash camera and a deputy's stop.",
        impact: "I repair that machine every month, and I do it myself because I can't afford to send a technician. The coin box was bent so badly that I had to order a new lock plate and lost two days of sales. It's a small business, and every drink I stock comes out of my own pocket.",
        genders: ["D": .male])

    static let busDriverYell = SmallCases.make(
        key: "story.busDriverYell",
        category: .publicOrder,
        headlines: ["Parent Screams at School Bus Driver in Front of Children", "Disorderly Conduct Charge at Elementary Bus Stop"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct by making a public disturbance at a school bus stop, on {DATE}.",
        ages: 24...55,
        victim: false,
        summary: "{D} stood in front of a school bus on {DATE}, blocking it, and yelled at the driver for ten minutes about a seating dispute with {D.his} son. Twenty children watched. The driver radioed dispatch and a deputy came. {DL} says the driver had been rough with the boy.",
        state: [E(.video, 3, "Bus Camera", "{D} in front of the bus with arms out, shouting; children at the windows."), E(.statement, 2, "Driver", "The driver says {D} used profanity and refused to move.")],
        defense: [E(.statement, 1, "Bruise", "{DL}'s son had a bruise on his arm the night before.")],
        role: "School bus driver",
        exam: [.direct("What route do you drive, and what time?", "\"I drive a morning bus route through the county. On {DATE}, I was stopped at 7:30 a.m. with about twenty children on board when {D} stepped in front of the bus.\""), .direct("What did {D} do?", "\"{D.He} stood in front of the bus with arms out, blocking it, and began shouting at me. The children could see and hear all of it through the windows.\""), .direct("What was the defendant shouting about?", "\"A seating dispute involving {D.his} child. {D.He} used profanity, demanded I get off the bus, and refused to move when I asked.\""), .direct("What did you do?", "\"I kept the doors closed and radioed dispatch at about 7:40. I told them I had a parent blocking the bus and children on board.\""), .direct("How long did it go on?", "\"About ten minutes in total. A deputy arrived at 7:50 and spoke to {DL}, and the bus finally rolled again a few minutes later.\""), .direct("How did the children react?", "\"Several were crying, and some kids pressed up against the windows. A few younger ones asked me if they were going to be late or in trouble.\""), .cross("Isn't it true the defendant's child had a bruise on the arm the day before?", "\"I heard that later. I didn't see any bruise that day, and I'm not aware of the child being hurt on my bus.\""), .cross("Did you ever touch the child's arm?", "\"I escort children to their seats when there's a conflict. I don't recall grabbing anyone, and I'd never intentionally hurt a student.\""), .cross("Did the defendant touch you or the bus?", "\"No. {D.He} stood in front of the bus and shouted. There was no physical contact with me or the vehicle.\""), .cross("Did you report any incident about the child before that morning?", "\"I filed a seating note about a disagreement between two students. I didn't file an injury report, because I wasn't aware of one.\""), .cross("Did the defendant say anything about calling the school?", "\"Yes. {DL} said the principal had told {DL} to call first. I told {DL} the call hadn't reached me, and nothing had been decided on my end.\"")],
        theory: ("{D} blocked a bus and screamed in front of children.", "A parent upset about a bruise."),
        allocution: "\"I was angry because my son came home the night before with a bruise on his arm and said the driver had grabbed him. I should have called the school and waited for an answer. Instead I stood in front of that bus and shouted, and I used words no child should hear. I'm sorry for scaring those kids.\"",
        truths: ("A child on the bus said the driver had grabbed the boy's arm.", "{DL} had been told by the principal to call, and screamed anyway."),
        defendant: [.direct("Why did you stand in front of the bus?", "\"My child came home the night before with a bruise on the arm and said the driver grabbed it. I wanted answers before that bus left again.\""), .direct("What did you say to the driver?", "\"I demanded to know what happened. I'll admit I was loud, and I used words I shouldn't have in front of children.\""), .direct("Had you tried to contact the school?", "\"Yes. I called the school and the principal told me to call back later in the day. I wasn't willing to wait.\""), .direct("Why not just wait for the bus at the stop?", "\"Because it was already pulling away with my child on it, and I had no assurance it would be safe that day.\""), .direct("What happened when the deputy arrived?", "\"I moved out of the road and spoke to the deputy. I explained about the bruise and said I was sorry the other children had been scared.\""), .direct("What would you do differently?", "\"I would have gone to the school office after the bus left. I let my anger decide for me and put the whole bus in an awkward spot.\""), .cross("You stood in the road in front of a school bus, didn't you?", "\"Yes, I did. I stood in front to stop it from leaving, and I know it was a dangerous place to stand.\""), .cross("The principal had told you to call, and you screamed instead?", "\"The principal told me to call. I was too angry to wait, and I regret not following that advice.\""), .cross("Twenty children watched you do it?", "\"I know there were children at the windows. I wasn't thinking about them, and I'm sorry for how it must have looked.\""), .cross("You cursed at the driver?", "\"I did. I used profanity, and I won't pretend I didn't. It was wrong, especially with children listening.\""), .cross("Did you see the driver actually grab your child?", "\"No, I wasn't there. A child on the bus told me, and my child showed me the bruise. I only know what I was told.\"")],
        openings: ("At 7:30 on a school morning, {D} stepped in front of a loaded bus, arms out, and shouted at the driver for ten minutes while twenty children watched. The bus camera recorded it and the driver radioed dispatch, and the State will show this was a deliberate disturbance of a school bus.", "{D}'s child came home with a bruise and said the driver grabbed the arm, and {DL} had been brushed off by the school. The defense says a worried parent lost control briefly, and the State should not turn that into a crime."),
        closings: ("Twenty children sat on that bus watching a parent block the road, curse the driver, and refuse to move. The camera shows it, the driver radioed dispatch, and the principal had already told {D} how to raise the complaint.", "{D} did not touch the driver or the bus, moved aside when the deputy came, and acted out of worry about a bruise on a child's arm. A parent's loud moment of fear is not the willful disruption the State must prove."),
        timeline: [(0, "7:30 a.m.: {DL} steps in front of the bus."), (0, "7:40 a.m.: the driver radios dispatch."), (0, "7:50 a.m.: a deputy arrives.")],
        identified: "The bus camera and the driver's radio call.",
        genders: ["D": .male, "V": .male])

    static let junkyardTires = SmallCases.make(
        key: "story.junkyardTires",
        category: .property,
        headlines: ["Four Tires and Rims Missing From Customer's Car at Junkyard", "Man Says He Bought Wheels at Flea Market"],
        law: "possStolen",
        spec: "Possessed four tires and rims valued at $780 belonging to {V}, knowing and having reasonable grounds to believe them stolen, on {DATE}.",
        ages: 20...58,
        victim: true,
        summary: "{V} woke on {DATE} to find {V.his} truck on cinder blocks, the wheels gone. A week later, a deputy found four matching tires and rims in {D}'s yard with the lug nut pattern scratched. {DL} says {D.he} bought them for $200 at a flea market.",
        state: [E(.physical, 3, "Tires and Rims", "Four tires and rims matching {V}'s receipt, in {D}'s yard.", .search), E(.document, 2, "Receipt", "{V}'s receipt for the tires, six months old.")],
        defense: [E(.statement, 1, "Flea Market", "{DL} says {D.he} bought the set for $200 from a vendor.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did you become involved in this case?", "\"{V} reported that the wheels were stolen off {V.his} truck overnight, leaving it on cinder blocks. About a week later I received a tip pointing to {D}'s yard.\""), .direct("What did {V}'s truck look like?", "\"It was sitting on cinder blocks in the driveway, all four wheels gone. The lug nuts were missing and there were scratches on the hubs.\""), .direct("What did you find at {D}'s yard?", "\"With {D.his} consent I looked around and found four tires and rims stacked behind a shed. They matched the make and size on {V}'s receipt.\""), .direct("What condition were the rims in?", "\"The lug nut seats had been scratched, as if someone had tried to alter or disguise them. Otherwise they were in good shape for six-month-old tires.\""), .direct("What did the defendant say about the tires?", "\"{DL} said they were bought for $200 at a flea market from a vendor. {DL} didn't have a receipt and couldn't give me the vendor's name.\""), .direct("How did {V} confirm that they were {V.his}?", "\"{V} came out the next day, matched the tire brand, the receipt, and the wear pattern on the tread, and identified them as the set stolen from the truck.\""), .cross("Isn't it true you searched with the defendant's consent?", "\"Yes, {D.he} agreed to let me look and was cooperative. I didn't have to get a warrant because I was invited.\""), .cross("Was the defendant's yard visible from the road?", "\"Partly. The shed was toward the back, but the tires were stacked where anyone walking through could see them. {DL} didn't hide them under cover.\""), .cross("Did you find any tools used to remove the wheels?", "\"No. I found nothing in the yard connecting {DL} to taking wheels off a truck, no jack and no blocks like the ones under {V}'s truck.\""), .cross("Could the same set of tires have been sold to someone else?", "\"The model and size are common. What matched was the brand, the receipt, and {V}'s own wear patterns, but I can't rule out a similar set.\""), .cross("Did anyone see the defendant take the wheels?", "\"No eyewitness told me that. All I have is where they ended up a week later.\"")],
        theory: ("{D} had {V}'s wheels in {D.his} yard.", "A flea market bargain."),
        allocution: "\"I should have asked a lot more questions about that set of tires. A vendor at the flea market said they came off a wrecked car, and the price made sense to me because I needed wheels for my truck. I never wanted to take anything from anyone. I'll return them today, and I'm sorry for the trouble.\"",
        truths: ("A neighbor saw {DL}'s truck leaving {V}'s street at 3 a.m.", "The vendor was arrested later and named {DL} as a buyer."),
        defendant: [.direct("Where did you get those tires and rims?", "\"At a flea market on a weekend morning. A vendor had a set of four for $200, and I needed wheels for my truck.\""), .direct("Did you ask where they came from?", "\"I asked, and the vendor said they came off a wrecked car. I took that at face value because the price made sense for used wheels.\""), .direct("Why was there no receipt?", "\"Flea market sales are cash and handshake. I didn't think to ask for a paper receipt for a few hundred dollars.\""), .direct("What did you do when the deputy came?", "\"I let the deputy look around the yard and showed the tires right away. I'd never hidden them, and I told the deputy exactly where I bought them.\""), .direct("What did you plan to do with them?", "\"I was going to put them on my truck. I hadn't gotten around to it yet, so they were stacked behind the shed.\""), .direct("How has this affected you?", "\"Sorry that {V} lost the wheels and sorry I wasn't more careful. If I had known they were stolen, I'd never have bought them.\""), .cross("You can't name the vendor, can you?", "\"No. I never got a name or a number, and I couldn't pick out the stall again without driving around. I realize that doesn't help my story.\""), .cross("The lug nut seats were scratched?", "\"I noticed the scratches but figured they came from a hard life on a different car. I didn't think someone was disguising them.\""), .cross("You paid $200 for four tires and rims of that quality?", "\"Yes. It was cheap, I knew it was a deal, and I should have wondered why it was so cheap.\""), .cross("Were you near {V}'s street the night of the theft?", "\"I was home that night. If someone says my truck was seen leaving {V}'s street, they're mistaken about the truck or the time.\""), .cross("You own a jack and cinder blocks, don't you?", "\"I have a jack for my own repairs. I don't have cinder blocks, and no one has shown that I used either on {V}'s truck.\"")],
        openings: ("{V} woke up to a truck sitting on cinder blocks with all four wheels gone. A week later a deputy found four matching tires and rims in {D}'s yard with the lug seats scratched, and the State will show they were {V}'s.", "{D} bought four used wheels from a flea market vendor, kept them stacked in plain view, and let a deputy search the yard without hesitation. The defense says that is how an innocent buyer behaves, and the State has no proof {DL} ever stood on {V}'s street."),
        closings: ("The brand, the size, and {V}'s receipt line up, and the rims turned up in {D}'s yard with scratches on the lug seats. Possession of recently stolen property with no receipt and no vendor is evidence a jury may weigh.", "Wheels look alike, nobody saw {D} near {V}'s truck, and the tires sat in the open where a deputy could see them. {DL} bought a cheap set from a stranger, which was careless, but being careless is not knowing it was stolen."),
        timeline: [(0, "Overnight: the wheels are stolen."), (7, "A deputy finds them in {DL}'s yard."), (8, "{V} identifies them.")],
        identified: "A deputy's tip and a search with consent.",
        impact: "I missed three days of work without a truck, and I'm paid by the day. I found it sitting on cinder blocks in my own yard with the wheels gone. I'd bought those tires a year before and was still paying them off. Nobody could tell me how long it would take to get them back.",
        genders: ["D": .male, "V": .female])

    static let deerStandTrespass = SmallCases.make(
        key: "story.deerStandTrespass",
        category: .property,
        headlines: ["Hunter's Stand Found on Posted Land", "Man Says Boundary Was Unclear"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a posted hunting tract, after being notified not to enter, on {DATE}.",
        ages: 24...66,
        victim: true,
        summary: "{V}'s 40-acre tract was posted with orange paint on the trees. On {DATE}, {V}'s trail camera caught {D} climbing into a deer stand at 5:30 a.m. {DL}'s truck was parked on a county road at the edge. {DL} says the paint was faded and {D.he} thought the tract was the neighbor's, who had given permission.",
        state: [E(.video, 3, "Trail Camera", "{D} climbs into the stand at 5:30 a.m."), E(.physical, 2, "Paint Marks", "Orange paint on trees every 100 feet around the tract.")],
        defense: [E(.statement, 1, "Neighbor", "The neighbor says {D.he} gave {D.him} permission to hunt on his side.")],
        role: "Wildlife officer",
        exam: [.direct("How is {V}'s property marked?", "\"It's a 40-acre tract. Orange paint marks are on trees about every 100 feet around the boundary, which is the standard way to post land in this state.\""), .direct("What did the trail camera show?", "\"At 5:30 a.m. on {DATE}, {D} walks up and climbs into a deer stand on the tract. The image is clear enough to see the stand and {DL}.\""), .direct("Where was {D}'s truck?", "\"Parked on a county road at the edge of the tract, near where the nearest paint-marked tree line begins. It was in view of the road.\""), .direct("When did {V} become aware?", "\"The same morning, when {V} reviewed the camera images. {V} then called me, and I came out and photographed the paint marks and the stand.\""), .direct("What did the defendant tell you?", "\"{DL} said the paint was faded, that {D.he} thought the land was the neighbor's, and that the neighbor had given permission to hunt.\""), .direct("What did your own look at the boundary show?", "\"Most of the paint was visible, though a few marks near the road were older. I could see one from the stand's direction of approach.\""), .cross("Isn't it true some of the paint was faded?", "\"Some of it near the road was, yes. I'd still say it was clear enough to see for someone looking at the trees.\""), .cross("Did the neighbor say the defendant could hunt there?", "\"The neighbor told me {DL} had permission to hunt the neighbor's own side. The neighbor didn't claim to have given permission to cross onto {V}'s land.\""), .cross("Where is the line between the properties?", "\"It runs along a survey marker. I understand a logging crew moved a marker some time back, and I haven't confirmed where the original line sat.\""), .cross("Did the defendant hide the truck?", "\"No. It was parked in the open at the roadside. Someone sneaking in might have hidden it, and {DL} didn't.\""), .cross("Did the defendant shoot anything on the land?", "\"No. {D.He} was only in the stand when {V} saw the image. I found no game and no spent casing.\"")],
        theory: ("{D} climbed into a stand on posted land.", "A hunter on a neighbor's permission and faded paint."),
        allocution: "\"I should have checked the property line before I climbed into that stand. The neighbor told me I could hunt his side, and the paint on the trees was so faded I thought it was his land. I walked about a quarter mile from the road and never meant to cross a line. I'm sorry for the mix-up.\"",
        truths: ("{DL} had hunted the tract before and been told to stay out.", "The neighbor's survey marker was moved by a logging crew, a forester confirmed."),
        defendant: [.direct("Why were you on that land?", "\"I was deer hunting with the neighbor's permission. I'd been told I could hunt the neighbor's side, and I thought the stand was on that side.\""), .direct("How did you find the stand?", "\"I walked from the road about a quarter mile and found it by a trail. I figured it was part of the neighbor's property, and I climbed up to wait for light.\""), .direct("Did you see any paint on the trees?", "\"I didn't notice any, but it was dark and I was looking at the ground. In the morning light the older marks near the road are hard to make out.\""), .direct("Had you hunted this area before?", "\"I've hunted nearby for years. I know the general area, but I never studied exactly where one tract ends and the other begins.\""), .direct("Where did you park, and why there?", "\"On the county road edge where I always park. It's open and visible, because I didn't think I was doing anything wrong.\""), .direct("What did you do when the wildlife officer spoke to you?", "\"I told the officer I'd had permission from the neighbor and gave the neighbor's name. I left the area as soon as the officer asked me to.\""), .cross("You'd hunted this tract before, hadn't you?", "\"I'd been near it, and some years back I may have been told to stay out of part of it. I took that to mean one particular corner.\""), .cross("You were told once to stay off this land, weren't you?", "\"I recall something like that years ago. I didn't think it applied to the same area, and the lines were never clear to me.\""), .cross("The paint is on the trees every 100 feet?", "\"So I've been told. I didn't see paint on the way in, and I'm not saying it wasn't there, only that I didn't notice.\""), .cross("Did you look for a boundary marker before climbing?", "\"No. I own that. I went by what I believed was the neighbor's line and didn't look further.\""), .cross("You climbed a stand that wasn't yours?", "\"I climbed a stand I believed was on land I was allowed to hunt. I know now I was wrong about where I was.\"")],
        openings: ("{V}'s 40-acre tract is posted with orange paint on trees every 100 feet. At 5:30 a.m. the trail camera caught {D} climbing into a deer stand there, and the State will show {DL} had hunted nearby and had been told to stay off.", "{D} had permission from the neighbor to hunt the neighbor's side, parked in plain view, and walked in on faded paint and a survey marker a logging crew had moved. The defense says {D.he} believed the land was lawful to hunt."),
        closings: ("The land was posted, the paint was visible, and {D} had hunted nearby before and had been told to stay out. A hunter who climbs a stand on posted land at 5:30 in the morning is on that land without consent.", "The paint near the road was faded, a logging crew moved the marker, and {D} parked openly and left when asked. A mistake about a boundary on a hard-to-read line is not the knowing entry on posted land the State must prove."),
        timeline: [(-30, "The tract is posted."), (0, "5:30 a.m.: {DL} climbs into the stand."), (0, "Morning: {V} reviews the camera.")],
        identified: "{V}'s trail camera.",
        impact: "I lease this land to my son, and every fall hunters wander in from the county road. We paint the trees orange every few years and put up signs, and people still come. Someone is always in a stand at dawn who doesn't belong there. It's hard to feel safe on your own property.",
        genders: ["D": .male, "V": .male])

    static let flagTheft = SmallCases.make(
        key: "story.flagTheft",
        category: .property,
        headlines: ["Flag and Pole Taken From Veteran's Front Yard", "Stolen American Flag Found in Teen's Truck"],
        law: "misdLarceny",
        spec: "Stole a flag and flagpole valued at $240 belonging to {V}, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "{V}, a retired Marine, found {V.his} flagpole and 3-by-5 flag missing from the front yard on {DATE}. A neighbor's camera showed a truck backing up at 1:15 a.m. The flag turned up draped in {D}'s truck bed. {DL} says {D.he} took it as a prank and meant to return it.",
        state: [E(.video, 3, "Neighbor's Camera", "A truck backs to the yard and two people lift the pole."), E(.physical, 2, "The Flag", "{V}'s flag, with a stitched name tag, in {D}'s truck.", .search)],
        defense: [E(.statement, 1, "Prank", "{DL} says it was a dare and {D.he} planned to return it.")],
        role: "Sheriff's deputy",
        exam: [.direct("What was reported to you on the morning of {DATE}?", "\"{V}, a retired Marine, found the flagpole and a 3-by-5 flag missing from the front yard. {V} was very upset and said that flag was part of {V.his} service.\""), .direct("What evidence did you collect from the neighborhood?", "\"A neighbor's camera showed a truck backing up to the yard at 1:15 a.m. and two people lifting the pole out of its sleeve and loading it.\""), .direct("How did you come to {D}'s truck?", "\"About three days later I got a tip. When I looked at the truck, the flag was draped across the bed, with a stitched name tag on one corner.\""), .direct("How did {V} identify the flag?", "\"By the stitched name tag and a repair {V} had sewn into the hem. {V} recognized it immediately and was visibly emotional.\""), .direct("What did the defendant say about it?", "\"{D} said it was a dare among friends and that {D.he} had planned to return it. {D.He} told me the flag was only borrowed.\""), .direct("Where was the pole?", "\"I didn't find the pole in {D.his} truck. I later learned a friend had it at another address.\""), .cross("Isn't it true you only found the flag, not the pole, in the defendant's truck?", "\"That's right. The flag was in the bed and the pole was at a friend's place, not with {DL}.\""), .cross("Can you tell from the camera which person was the defendant?", "\"No. The footage is dark and shows two people lifting the pole. I can't say which of them was {DL}.\""), .cross("Did the defendant try to hide the flag?", "\"It was lying in the open truck bed. It wasn't wrapped or covered, and anyone passing the truck would see it.\""), .cross("Did the defendant say who else was involved?", "\"{DL} mentioned a friend but wasn't specific. I followed that up with the friend afterward, and the pole was found there.\""), .cross("Did the defendant attempt to sell or keep it?", "\"I have no evidence of any sale. The flag was still with {D.his} truck three days later, in good condition.\"")],
        theory: ("{D} took a veteran's flag and pole at night.", "A dare, and a flag meant to go back."),
        allocution: "\"It was a stupid dare, and I'm ashamed of it. We'd been joking that evening, and I thought we'd put the flag back in a day or two. I didn't know what it meant to the man who flew it. I'm sorry to {V} and to every veteran who saw that pole empty.\"",
        truths: ("A friend's text said 'flag is ours, we'll keep it.'", "The pole was found in the friend's yard, and {DL} never touched it."),
        defendant: [.direct("How did you end up with the flag?", "\"A friend dared me to take it. We'd been joking about it that evening, and I thought we could return it in a day or two.\""), .direct("Who actually took the pole?", "\"My friend did. I never touched the pole, and I didn't see where it went. I just wound up with the flag in my truck.\""), .direct("Why didn't you return it?", "\"I meant to. I kept putting it off, and then the deputy showed up. I wasn't hiding it, and it was in the truck bed the whole time.\""), .direct("Did you know whose flag it was?", "\"I knew it belonged to the person who lived there. I didn't know {V} was a retired Marine until the deputy told me, and I felt sick hearing it.\""), .direct("What would you say to {V}?", "\"I am truly sorry. It was a stupid prank and I never should have let it go that far. I understand why it hurt.\""), .direct("What did you tell the deputy?", "\"The truth. I said it was a dare, that I planned to bring it back, and that I would help get everything returned.\""), .cross("You were in the truck at 1:15 in the morning on {V}'s street?", "\"I was out with friends that night. I won't deny that I was in the truck.\""), .cross("You helped lift the pole?", "\"I'm told two people did it. I don't remember touching the pole. I know the flag ended up with me, and I can't prove otherwise.\""), .cross("A text from your friend said, flag is ours, we'll keep it?", "\"Yes, my friend sent that. I didn't agree with it. I'd said I would return it, and I never replied that we'd keep it.\""), .cross("You never contacted {V} to give it back?", "\"No. In hindsight, yes. I felt too embarrassed, and I was waiting for a good time. That wasn't right.\""), .cross("Taking a flag from a veteran's yard at night isn't a prank, is it?", "\"Looking back, no. It was a bad dare. I thought only of the joke and not of what the flag meant to {V}.\"")],
        openings: ("At 1:15 in the morning a truck backed up to a retired Marine's yard and two people lifted out a flagpole and a 3-by-5 flag. Three days later the flag, with {V}'s stitched name tag, was draped across the bed of {D}'s truck.", "{D} says this was a dare among friends, that the flag was meant to go back, and that another person has the pole. The defense says the State must prove {DL} intended to keep what was taken."),
        closings: ("The flag was taken from {V}'s yard in the dark and found in {D}'s truck three days later with {V}'s name tag on it. A dare does not make a flag taken from a veteran's yard anything other than taken.", "The pole was found at a friend's house, the flag sat openly in the truck bed, and {D} told the deputy right away it was a prank to be returned. A bad dare with no intent to keep the flag does not satisfy the State's burden."),
        timeline: [(0, "1:15 a.m.: the flag is taken."), (0, "Morning: {V} finds the empty yard."), (3, "A deputy finds the flag in {DL}'s truck.")],
        identified: "A neighbor's camera and a deputy's tip.",
        mood: .wantsConviction,
        impact: "That flag was folded at my brother's funeral, and I flew it every morning since. I stood in my yard at dawn and found only an empty pole. It isn't a piece of cloth to me. I served for twenty years, and I wasn't ready to see it dragged around in the back of a truck.",
        genders: ["V": .male])

    static let borrowedTruck = SmallCases.make(
        key: "story.borrowedTruck",
        category: .property,
        headlines: ["Man Kept Friend's Truck for Three Weeks", "Larceny Charge Over Borrowed Pickup"],
        law: "misdLarceny",
        spec: "Stole a pickup truck valued at $900 belonging to {V}, on {DATE}.",
        ages: 22...58,
        victim: true,
        summary: "{V} lent {D} an old pickup for a weekend job on {DATE}. {DL} kept it for three weeks, ignored {V}'s calls, and was seen driving it across the county. {V} reported it stolen. {DL} says {V} owed {D.him} $400 for work and said to keep it until paid.",
        state: [E(.statement, 3, "{V}'s Account", "{V} says the loan was for the weekend only."), E(.document, 2, "Texts", "Seven unanswered texts from {V} over two weeks.")],
        defense: [E(.statement, 1, "Debt", "{DL} says {V} owed {D.him} $400.")],
        role: "Sheriff's deputy",
        exam: [.direct("What was reported to you?", "\"{V} reported that an old pickup lent to {D} for a weekend job had not been returned after three weeks. {V} said {DL} had ignored the calls and texts.\""), .direct("When was the truck lent?", "\"On a Friday. {V} says the loan was for the weekend only, so {DL} could finish a job, and the truck was due back Monday.\""), .direct("What did {V}'s phone show?", "\"Seven unanswered texts to {DL} over two weeks, each asking for the truck back. {V} showed them to me on the phone.\""), .direct("What happened when {V} reported it stolen?", "\"About three weeks after the loan, I put out the plate and a deputy later spotted the truck being driven across the county. We stopped it.\""), .direct("What did {D} tell you at the stop?", "\"{DL} said {V} owed {DL} $400 for work and had said to keep the truck until paid. {DL} said it was security, not theft.\""), .direct("What condition was the truck in?", "\"Run-down but intact, with the same plate and no obvious new damage. It had a fresh load of tools in the bed.\""), .cross("Isn't it true the defendant did work for {V}?", "\"{V} agreed {DL} had done some work. {V} disputed that it was $400 and said the debt had been settled.\""), .cross("Did {V} ever text that the defendant could use the truck for a while?", "\"I saw a text where {V} offered {DL} the truck for a while. {V} explained that meant the weekend job, and I can't say how {DL} read it.\""), .cross("Did the defendant hide the truck?", "\"No. It was driven openly across the county in daylight, and it had the same plate on it the entire time.\""), .cross("Did the defendant answer any text during the three weeks?", "\"One text reply came, which said, I'll keep it till you pay up. That was the only response I saw.\""), .cross("Did {V} ever demand it back directly in person?", "\"I don't believe so. {V} stuck to calls and texts until the report was filed.\"")],
        theory: ("{D} kept a borrowed truck for three weeks and ignored calls.", "A worker holding a truck until a debt was paid."),
        allocution: "\"I should have gone to small claims court. {V} lent me the truck for a weekend job, and I kept it because I was owed four hundred dollars for work and I'd asked more than once. That wasn't the right way to collect. I'm sorry for the weeks {V.he} was without it, and I'll bring it back.\"",
        truths: ("{DL}'s text said 'I'll keep it till you pay up.'", "{V}'s own text offered to let {DL} use it 'for a while.'"),
        defendant: [.direct("How did you come to have the truck?", "\"{V} lent it to me for a weekend job. I'd done work for {V} before, and the truck made it easier to haul equipment.\""), .direct("What did {V} owe you?", "\"Four hundred dollars for work I'd done earlier that month. I asked for it more than once, and {V} kept putting me off.\""), .direct("What was your understanding about keeping the truck?", "\"When I raised the money, {V} said something like keep it until we settle up. I took that as permission to hold it as security.\""), .direct("Why didn't you answer the calls?", "\"I got the texts, but I figured if I talked to {V} we'd just argue. I sent one reply saying I'd keep it until I got paid.\""), .direct("What did you do with the truck while you had it?", "\"I used it for jobs and for getting to work. I took good care of it, and I never meant to sell it or hide it.\""), .direct("What did you want when you were stopped?", "\"To get paid and give the truck back. I told the deputy right away what the arrangement was.\""), .cross("The loan was for a weekend, wasn't it?", "\"It started as a weekend loan. After the money dispute, I understood it differently, and I know {V} doesn't agree.\""), .cross("You kept it for three weeks?", "\"Yes, three weeks. I won't say otherwise, and I understand why {V} got worried when no one answered.\""), .cross("You ignored seven texts?", "\"I read them and didn't answer most. I was angry about the money and not thinking about how it looked.\""), .cross("Did {V} agree in writing that you could keep it until paid?", "\"No. It was a spoken remark, and I can't show it to you. The only writing is my own text saying I'd keep it.\""), .cross("You never told {V} you were holding it as security until the last text?", "\"Right, not until then. I should have said so at the start instead of going silent, and I see that now.\"")],
        openings: ("{V} lent {D} an old pickup for a weekend job, and three weeks later it was still gone, with seven texts unanswered. The State will show {DL} kept the truck without permission, ignored every call, and was found driving it across the county.", "{V} owed {D} $400 for work and said to keep the truck until it was paid. The defense says this is a payment dispute between two people, not a theft, and the State cannot prove {DL} meant to deprive {V} of the truck."),
        closings: ("A weekend loan became a three-week absence, with seven texts ignored and the truck seen across the county. {D}'s own reply, I'll keep it till you pay up, shows {DL} knew it was not {D.his} to keep.", "{V} offered the truck, {V} owed money, and {D} said openly in a text what {DL} was doing. A dispute over a debt is a civil matter, and the State cannot show {DL} intended to steal the truck."),
        timeline: [(0, "Friday: {V} lends the truck."), (14, "{V} sends the seventh text."), (21, "{V} reports it stolen; deputies find it.")],
        identified: "{V}'s report and a deputy's sighting.",
        impact: "I couldn't get to my job for three weeks, and I'm not paid unless I show up. I lent that old pickup in good faith to a man I'd known for years. I called and texted day after day and heard nothing back. I walked, begged rides, and lost my place on two crews.",
        genders: ["D": .male, "V": .male])

    static let donationBox = SmallCases.make(
        key: "story.donationBox",
        category: .property,
        headlines: ["Church Donation Box Emptied", "Man Seen Leaving Sanctuary With Cash Box"],
        law: "misdLarceny",
        spec: "Stole $212 in cash from a donation box belonging to {V}, a church, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "A church secretary found the donation box in the vestibule empty on {DATE}. A camera showed {D} leaving at 2:10 p.m. with a folded coat over an arm and a bulge. {DL} says {D.he} stopped to pray and the coat held {D.his} own papers.",
        state: [E(.video, 3, "Vestibule Camera", "{D} lifts the lid of the box and slides cash into a coat."), E(.document, 2, "Count Sheet", "The box held $212 at the Sunday count.")],
        defense: [E(.statement, 1, "Prayer", "{DL} says {D.he} was in the sanctuary to pray.")],
        role: "Church secretary",
        exam: [.direct("What is your role at the church?", "\"I'm the church secretary. I count the donation box with another volunteer each Sunday, and I keep the count sheets in the office.\""), .direct("What did you find on {DATE}?", "\"The donation box in the vestibule was empty when I went to check it that afternoon. The box had held $212 at the Sunday count.\""), .direct("What did the vestibule camera show?", "\"At about 2 p.m. {D} is in the vestibule, lifts the lid of the donation box, and slides cash into a folded coat held over an arm.\""), .direct("When did {D} leave?", "\"At 2:10 p.m. The video shows {DL} walking out with the coat folded across an arm, looking as if it held something.\""), .direct("Who else was in the building?", "\"A few people were in the sanctuary for a quiet afternoon service. I was in the office with the door open and didn't see anything myself.\""), .direct("How did you know the box wasn't just emptied by a church member?", "\"We count at the Sunday service and lock the cash in the safe. The donation box shouldn't have held anything that afternoon except new gifts.\""), .cross("Isn't it true you didn't see the defendant take any money yourself?", "\"That's correct. I only saw what the camera shows. I was in the office at the time.\""), .cross("Does the video show cash going into the coat?", "\"It shows the lid lifted and a hand moving. The angle is from above and behind, so I can't see the bills themselves.\""), .cross("Was the box locked?", "\"It has a simple latch, not a lock. Anyone could lift the lid. We keep it that way for ease of donating.\""), .cross("Did the defendant go into the sanctuary?", "\"I believe so, for part of the afternoon. A churchgoer told me {DL} was in the pews for the hour, though I can't confirm the whole time.\""), .cross("Could someone else have taken it before the defendant?", "\"It's possible. I didn't check the box between the Sunday count and that afternoon, so I can't rule out someone else.\"")],
        theory: ("{D} emptied a church donation box.", "A man who came to pray."),
        allocution: "\"I walked into that church on a hard day and I did something I'm sorry for. I was desperate and I wasn't thinking of the people it hurt. I'll repay the church, every dollar I took or the court says I owe. I stopped to pray in that sanctuary and I meant it.\"",
        truths: ("The coat had bills in the lining when {DL} was stopped.", "A churchgoer said {DL} was in the pews all hour and never near the box."),
        defendant: [.direct("Why were you at the church that afternoon?", "\"I stopped in to pray. I'd had a hard week and wanted a quiet moment in the sanctuary before the afternoon service.\""), .direct("What were you doing in the vestibule?", "\"I paused by the donation box. I thought about giving something, lifted the lid to look, and decided not to.\""), .direct("What was in the coat on your arm?", "\"My own papers, a folder I had with me from earlier. It was a heavy coat, and the folder made it bulge.\""), .direct("Did you take any money from the box?", "\"No. I never took a dollar from that box. I've gone to this church for years and wouldn't take from the offering.\""), .direct("How long were you inside?", "\"About an hour, mostly in the pews. A churchgoer sitting nearby saw me there, and I never went near the box until I left.\""), .direct("What did you do when you were stopped?", "\"I told the deputy I'd come to pray and that the coat held my papers. I showed what was in it without any argument.\""), .cross("You lifted the lid of the box, didn't you?", "\"I did lift it. I wanted to see whether to give, and I put it back. I understand that looks bad on a camera.\""), .cross("The video shows your hand moving as the lid is lifted?", "\"That's right. I was handling the lid and my coat at once, and it looks different than it was.\""), .cross("You left at 2:10 with the coat folded over your arm?", "\"I did, the coat was in my hands because it was warm inside. That's why it was folded rather than worn.\""), .cross("Did anyone find money in the lining of your coat?", "\"The deputy found some bills in the lining. Those were mine from before, and I'd forgotten they were there.\""), .cross("You can't prove that cash in the lining was yours?", "\"No, I can't show a receipt for it. It was ordinary pocket money, and I don't have anything to document it.\"")],
        openings: ("On a quiet afternoon, the church's vestibule camera recorded {D} lifting the lid of the donation box and moving a folded coat to cover a hand. By 2:10 {DL} was gone and the box that held $212 at the Sunday count was empty.", "{D} came to pray, sat in the pews for an hour, and left with a coat holding personal papers. The defense says no one saw {DL} take a dollar, and the State is asking the jury to read a theft into a worshiper's visit."),
        closings: ("The camera shows {D} at the box, the lid up, the coat in position, and a quick exit. The box was full on Sunday and empty by 2:10, and bills in the lining of the coat complete the picture.", "No one saw money taken, the box has no lock, and a churchgoer places {D} in the pews all hour. The State has a camera angle that shows a lifted lid and nothing more, and that leaves reasonable doubt."),
        timeline: [(0, "2 p.m.: {DL} in the vestibule."), (0, "2:10 p.m.: {DL} leaves."), (0, "The secretary finds the box empty.")],
        identified: "The vestibule camera.",
        impact: "That box paid for our food pantry, and we count on it every month. A few dollars from a hundred people at a time fed forty families in the winter. When I found it empty, I had to call each volunteer and tell them. We rationed canned goods until the next Sunday.",
        genders: ["D": .male])

    static let skateboardRefuse = SmallCases.make(
        key: "story.skateboardRefuse",
        category: .publicOrder,
        headlines: ["Teen on Skateboard Ignored Deputy's Order to Stop", "Resisting Charge Over a Skate Park Dispute"],
        law: "resisting",
        spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, in discharging a duty of the officer's office, on {DATE}.",
        ages: 18...26,
        victim: false,
        summary: "A deputy told {D} to stop skateboarding on a church's steps on {DATE}. {DL} kicked off, rolled away, and refused to give a name when the deputy caught up. The deputy took {DL}'s arm and {DL} pulled loose. {DL} says the steps were public and the deputy never explained why.",
        state: [E(.video, 3, "Body Camera", "The deputy says stop, {D} rolls away; later pulls loose from a hand on the arm."), E(.document, 2, "Church Complaint", "The church asked deputies to move skaters off the steps.")],
        defense: [E(.statement, 1, "Public Steps", "{DL} says the steps front a public sidewalk.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you see on the church steps that afternoon?", "\"I saw {D} skateboarding on the front steps of the church, riding down and kicking the board against the stone. The steps are church property.\""), .direct("What did you ask {D} to do?", "\"I told {D.him} to stop and asked for a name. {D.He} kicked off on the board, rolled away, and would not identify {D.himself}.\""), .direct("What happened when you caught up?", "\"I took {D.his} arm to stop the board, and {D.he} pulled free. It was a short struggle, and I made the arrest after that.\""), .direct("How did you learn about the skaters on the church steps?", "\"The church's secretary called the sheriff's office and said skaters had been on the front steps all afternoon. I was dispatched to move them along.\""), .direct("Where were you when you caught up to the defendant?", "\"About a block down the sidewalk. {D.He} had rolled away when I first told {D.him} to stop, and I followed on foot and caught up near a corner.\""), .direct("What did you say to the defendant before you took {D.his} arm?", "\"I identified myself, repeated that the church wanted the steps cleared, and asked for a name. {D.He} refused to answer and started to move off.\""), .cross("The steps looked public, didn't they?", "\"They look open, but the church owns them and the front has signs. I can see why a young person would not be sure.\""), .cross("{D} never struck you, did {D.he}?", "\"No. {D.He} pulled loose and nothing more. I was not injured, and I never saw a fist or a kick.\""), .cross("How clearly did you tell the defendant who you were and why you were asking?", "\"I was in uniform and I believe I said it plainly. {D.He} may have had a different impression of how clear I was.\""), .cross("Did the church give you a written trespass notice for the defendant?", "\"No. The church asked deputies to move skaters off the steps, but nothing was in writing about {DL} specifically.\""), .cross("How much force did you use when you took the defendant's arm?", "\"A hand on the upper arm, with no strike or takedown. {D.He} pulled free, and I let go and did not pursue any further.\"")],
        theory: ("{D} rolled away from a deputy and pulled free.", "A teen who didn't understand why."),
        allocution: "\"I should have stopped when the deputy asked me to, and I'm sorry that I didn't. I didn't understand why I was being stopped, and I was nervous and wanted to get out of there. I shouldn't have pulled away from the deputy's hand. I'll stay off those steps from now on, and I'll listen better.\"",
        truths: ("{DL} had been warned off the steps twice that month.", "The deputy never said he was a deputy until the arm grab, the video showed."),
        defendant: [.direct("Why were you on those steps?", "\"I was skateboarding with a friend. The steps are wide and smooth, and a lot of people use that area. I did not think it was a problem.\""), .direct("Why did you roll away from the deputy?", "\"I did not understand why I was being stopped. I got nervous and I just wanted to get out of there, so I pushed off.\""), .direct("Why did you pull away when the deputy took your arm?", "\"I was scared. I pulled without thinking about it. I never swung at anyone and I never tried to hurt the deputy.\""), .direct("How old are you, and what were you doing that afternoon?", "\"I was skating with a friend after school. We started at a park and ended up on the steps because they're smooth and have a good rail.\""), .direct("What did the deputy say when you first rolled away?", "\"Something like 'stop.' I didn't hear a reason, so I thought I was in trouble for skating and I kept going.\""), .direct("What did you do after you pulled away?", "\"I stopped almost at once and said I was sorry. I didn't run, and I didn't hit anyone.\""), .cross("You had been told before to stay off those steps, hadn't you?", "\"By people from the church, yes. I never had a deputy tell me. I thought the church people were being territorial.\""), .cross("You refused to give a name when asked, correct?", "\"I did, because I did not know why I was being asked. I should have just said it, and I see that now.\""), .cross("The deputy was in uniform. Wasn't it obvious who was talking to you?", "\"I could see the uniform, but it was not clear what I was doing wrong. I am not claiming I was perfect.\""), .cross("Did you give your name later?", "\"Yes. I gave my full name and my address as soon as I understood why they were asking.\""), .cross("The church asked skaters to leave and you'd been told before. Why were you back on the steps?", "\"Nobody ever told me it was against the law, only that the church didn't like it. I didn't realize it could get me in trouble.\"")],
        openings: ("A deputy told {D} to stop skateboarding on a church's steps and give a name. {DL} rolled away, then pulled free when the deputy took an arm. The State will show that this was resisting a lawful stop.", "The steps looked public, no one explained why {D} was stopped, and {D.he} panicked. The defense will show a young person frightened by a sudden grab, not someone fighting an officer."),
        closings: ("The deputy asked, {D} rolled away, and then {DL} pulled loose when stopped. That is delaying an officer, and it does not matter that no one was struck.", "{D} was never told why. A scared young person pulled an arm free and that was all. Confusion is not criminal, and the State has not shown {DL} knew what the deputy wanted."),
        timeline: [(0, "Afternoon: the church calls deputies."), (0, "{DL} rolls away."), (0, "The deputy catches up and grabs {D.his} arm.")],
        identified: "The deputy's body camera.")

    static let fireAlarmPull = SmallCases.make(
        key: "story.fireAlarmPull",
        category: .publicOrder,
        headlines: ["Tenant Pulled Apartment Fire Alarm After Argument", "False Alarm Brought Three Engines at 2 A.M."],
        law: "falseReport",
        spec: "Willfully made a false report that a building was on fire by pulling a fire alarm, on {DATE}.",
        ages: 20...50,
        victim: false,
        summary: "Three engines were dispatched to an apartment building at 2:05 a.m. on {DATE} when the alarm sounded. There was no fire. A hallway camera showed {D} pulling the lever after arguing with a neighbor. {DL} says {D.he} tripped and caught the lever.",
        state: [E(.video, 3, "Hallway Camera", "{D} walks to the pull station and pulls the lever at 2:05 a.m."), E(.document, 2, "Dispatch Log", "Three engines; 41 residents evacuated.")],
        defense: [E(.statement, 1, "Tripped", "{DL} says {D.he} tripped on the rug and grabbed the wall.")],
        role: "Fire captain",
        exam: [.direct("What was the call that night?", "\"At 2:05 a.m. on {DATE}, dispatch reported a fire alarm activation at an apartment building. We rolled three engines and a captain.\""), .direct("What did you find on arrival?", "\"No fire, no smoke, nothing burning. Forty-one residents had been evacuated and were standing in the parking lot in their sleepwear.\""), .direct("How did you determine the alarm was pulled?", "\"The pull station in the second-floor hallway had been activated, and the building's hallway camera showed who did it.\""), .direct("What does the hallway camera show?", "\"At 1:50 a.m. {D} argues with a neighbor in the hall. At 2:05 {DL} walks straight to the pull station and pulls the lever.\""), .direct("How long was your crew committed?", "\"About fifteen minutes to sweep the building, until roughly 2:20. Three engines were tied up and could not answer anything else in the district.\""), .direct("How did residents respond?", "\"Several families were frightened, some were elderly, and a few children were crying. People were out in the cold until we cleared the building.\""), .cross("Isn't it true you can't hear what was said in the argument?", "\"The camera has no audio, so I only see two people gesturing. I can't tell what was said or who was angrier.\""), .cross("Does the video show {D} falling or stumbling?", "\"The angle shows {DL} reaching the station. I can't tell from my viewing whether a stumble came first, and I haven't ruled one out.\""), .cross("Was the pull station in good working order?", "\"Yes, it works as designed. It needs a firm pull of the lever, though a hard grab on the way down could do it.\""), .cross("Is there a rug near the pull station?", "\"There is a hallway runner, and the edge near the station was curled up when I looked. I didn't test whether it could catch a foot.\""), .cross("Did the defendant flee after the alarm?", "\"No. {D.He} stayed in the hallway and was still there when deputies arrived, and gave a statement right away.\"")],
        theory: ("{D} pulled the alarm after an argument and sent three engines.", "A trip against a pull station."),
        allocution: "\"I was angry at my neighbor that night, and I'm sorry for how I acted in the hallway. I'd had an argument about noise and I was walking toward my door when I caught myself on the wall near that lever. I never meant to bring three fire engines to a quiet building at two in the morning.\"",
        truths: ("{DL} told a friend 'I wanted to wake them up.'", "The rug had a curled edge and a second tenant tripped there later."),
        defendant: [.direct("What happened in the hallway that night?", "\"I'd had an argument with a neighbor about noise around 1:50. I was upset and walking toward my door when it happened.\""), .direct("Did you pull the alarm on purpose?", "\"No. There's a rug with a curled edge near the pull station and I tripped on it. I grabbed at the wall to catch myself.\""), .direct("How did the lever end up pulled?", "\"My hand hit the station as I fell forward, and the lever came down under my weight. Then the alarm went off and I froze.\""), .direct("What did you do after the alarm sounded?", "\"I stood there and said I didn't mean to. I stayed until the captain and deputies arrived, and I answered what they asked.\""), .direct("How has this affected you?", "\"Awful. Forty-one people were out in the cold because of me, and some of them are elderly. I'd apologize to every one.\""), .direct("Do you know of anyone else who tripped on that rug?", "\"A neighbor tripped on it a few days afterward. It's been curled up for weeks, and I'd mentioned it to the manager.\""), .cross("You were angry at your neighbor right before it happened?", "\"I was upset, yes. We'd gone back and forth about noise, and I won't pretend it was a friendly conversation.\""), .cross("You told a friend you wanted to wake them up, didn't you?", "\"I said something like that to a friend later, in frustration. I meant I was annoyed at being kept awake, and not that I'd pulled the alarm.\""), .cross("The video shows you walking straight to the pull station?", "\"It looks that way on the video, but I was walking along the wall with my head down. The station is right by my path.\""), .cross("You didn't try to reset the alarm or warn anyone?", "\"I couldn't reset it, and I didn't know how. I just stood there stunned until the captain came up.\""), .cross("Isn't it convenient that you tripped exactly there?", "\"I know how that sounds. But the rug has been a hazard for weeks, and I wouldn't have invented a trip if it hadn't happened.\"")],
        openings: ("At 2:05 in the morning an apartment building's alarm went off, three engines raced out, and 41 residents stood in the cold for a fire that did not exist. The hallway camera shows {D} arguing with a neighbor and then walking to the pull station.", "{D} tripped on a curled rug beside the pull station and caught the lever on the way down. The defense says there was no fire, no lie, and no intent to cause a false alarm, only a stumble that sent a building outside."),
        closings: ("The camera shows the argument at 1:50 and the pull at 2:05, and a friend heard {D} say the aim was to wake them up. Three engines and 41 residents paid for that, and {DL} is the person who pulled the lever.", "The rug had a curled edge, a second tenant tripped there later, and {D} stayed to answer questions. The State must prove a deliberate false alarm, and a stumble against a pull station is an accident."),
        timeline: [(0, "1:50 a.m.: an argument in the hallway."), (0, "2:05 a.m.: the alarm sounds."), (0, "2:20 a.m.: engines clear the building.")],
        identified: "The hallway camera.",
        mood: .wantsConviction)

    static let dryerClothes = SmallCases.make(
        key: "story.dryerClothes",
        category: .property,
        headlines: ["Woman Took Clothes From Laundromat Dryer", "Laundromat Camera Shows Bag of Someone Else's Laundry"],
        law: "misdLarceny",
        spec: "Stole clothing valued at $210 belonging to {V}, on {DATE}.",
        ages: 19...60,
        victim: true,
        summary: "{V} left a load of laundry in a laundromat dryer on {DATE} and came back to find the dryer empty. The camera showed {D} taking the clothes into a black bag and leaving. {DL} says {D.he} thought the dryer was {D.his} and had left a similar load there.",
        state: [E(.video, 3, "Laundromat Camera", "{D} opens dryer six, lifts the clothes into a bag, and leaves."), E(.document, 2, "Value", "Work uniforms and a coat, $210.")],
        defense: [E(.statement, 1, "Own Load", "{DL} says {D.he} had a similar load in a dryer that day.")],
        role: "Laundromat attendant",
        exam: [.direct("What is your job at the laundromat?", "\"I'm the attendant on the evening shift. I keep the machines running, handle change, and review our camera when a customer reports a problem.\""), .direct("What did {V} report on {DATE}?", "\"{V} had started a dryer that evening and came back to find it empty. {V} said the load was work uniforms and a coat.\""), .direct("What does the camera show?", "\"{D} opens dryer six, lifts the clothes into a black bag, and leaves the building. The whole thing takes less than two minutes.\""), .direct("What was the value of the clothes?", "\"About $210. {V}'s load held several work uniforms that {V} had to replace for the next shift, plus a coat.\""), .direct("How did you identify {D}?", "\"{D.He} had been in the laundromat earlier and paid with a card at the change machine. The card record matched {D.his} name.\""), .direct("What happened to the clothes?", "\"A deputy later found them in the trunk of {DL}'s car. They were still in the black bag and still warm and folded.\""), .cross("Isn't it true dryer six and dryer eight are next to each other?", "\"They're in the same row, side by side. It's an easy mix-up if someone has a load going in either one.\""), .cross("Did the defendant have a load of laundry in another dryer?", "\"I believe {D.he} had a load in dryer eight. It was still there when the deputy arrived.\""), .cross("Did the defendant try to hide anything on camera?", "\"Not really. {D.He} acted openly, took the clothes in plain view, and didn't hurry or look around.\""), .cross("Were the dryers labeled with names or tickets?", "\"No. We don't tag loads. A customer just walks up and opens whichever dryer is theirs, so mistakes happen now and then.\""), .cross("Did you speak with the defendant that evening?", "\"Only to say good evening. I didn't see {DL} take the clothes. I only learned from the camera afterward.\"")],
        theory: ("{D} took a stranger's laundry.", "A woman who mistook a dryer."),
        allocution: "\"I'll replace the uniforms, the coat, and anything else that was in that bag. I came back when my timer ran out and went to take my clothes from the dryer, and I lost track of which machine was mine. I'm sorry to {V} for the mix-up and for the trouble it caused.\"",
        truths: ("The clothes were sized wrong for {DL} and found in {D.his} trunk.", "{DL}'s own load was in dryer eight and was still there."),
        defendant: [.direct("What were you doing at the laundromat?", "\"I had a load of my own in dryer eight. I came back when the timer ran out and went to take my clothes.\""), .direct("Why did you open dryer six?", "\"I thought it was mine. I'd put my load in one of the machines near the end of the row, and I lost track of which one.\""), .direct("What did you notice about the clothes?", "\"They were warm and about the right amount, so I didn't look closely. I bagged them quickly because I was tired and in a hurry.\""), .direct("When did you realize something was wrong?", "\"When I got home and looked at them. I saw they were uniforms in a size that didn't fit, and I thought I should return them.\""), .direct("What did you do then?", "\"I meant to bring them back the next day. A deputy came to the door before I'd gone, and I handed the bag over.\""), .direct("How do you feel about this?", "\"Embarrassed and sorry. I'd never knowingly take someone's laundry, and I'd replace anything lost.\""), .cross("The clothes were sized wrong for you, weren't they?", "\"Yes, they were different sizes. I didn't look at them in the laundromat, and I wish I had.\""), .cross("The clothes were in your trunk, not in your house?", "\"I put the bag in the trunk when I left. I hadn't carried it in yet, because I planned to sort laundry later.\""), .cross("You had a load in dryer eight, which was still there?", "\"Yes. When I took the other clothes, I never checked my own dryer. I don't know why I didn't.\""), .cross("You walked right past the other dryer to open six?", "\"I did, and I didn't think about it at the time. It's an easy mistake in a long row, but I know it looks odd.\""), .cross("You didn't call the laundromat once you realized?", "\"No. I meant to the next morning. I wasn't trying to keep them, but I did wait too long.\"")],
        openings: ("On the laundromat camera, {D} opens dryer six, lifts out a stranger's work uniforms and coat, bags them, and walks out. Deputies found that bag in the trunk of {D.his} car, and the State will show the clothes were worth $210.", "{D} had a load in dryer eight, opened the wrong machine in a long row, and handed the bag over to a deputy the moment asked. The defense says taking the wrong clothes by mistake is not larceny."),
        closings: ("The camera shows {D} open the machine, bag the clothes, and drive off, and the bag turned up in the trunk. The uniforms were the wrong size and the dryer {DL} used was not the one holding {D.his} own load.", "Two dryers side by side, no tags, a tired customer, and {D}'s own load still in the next machine. A mistaken grab is not an intent to steal, and {D.he} gave everything back."),
        timeline: [(0, "Evening: {V} starts the dryer."), (0, "{DL} takes the clothes."), (0, "{V} finds the dryer empty.")],
        identified: "The laundromat camera.",
        impact: "I lost two work uniforms and my winter coat out of that dryer, and I can't afford to replace them all at once. Without the uniforms I couldn't work my shift, and my boss wasn't happy about it. I did my wash on a Sunday night. I'd just like my things back.",
        genders: ["D": .female])

    static let softballFieldFight = SmallCases.make(
        key: "story.softballFieldFight",
        category: .violent,
        headlines: ["Rec League Softball Dispute Ends in a Punch", "Coach Charged After Umpire Dispute"],
        law: "simpleAssault",
        spec: "Assaulted {V}, an umpire, by striking {V.him} in the face with a fist, on {DATE}.",
        ages: 28...60,
        victim: true,
        summary: "During a rec league softball game on {DATE}, {D}, a coach, argued a called third strike with {V}, the umpire. According to {V}, {DL} hit {V.him} in the face when {V.he} turned to leave. {DL} says {V} stepped on {D.his} foot and {D.he} pushed {V.him} off.",
        state: [E(.statement, 3, "Players", "Two players saw a closed fist to the face."), E(.document, 2, "Urgent Care Note", "A split lip and a loose tooth.")],
        defense: [E(.statement, 1, "Foot", "{DL} says {V} stepped on {D.his} foot.")],
        role: "Recreation department supervisor",
        exam: [.direct("What was your role at the softball game?", "\"I supervise the recreation department leagues. I was at the field that night when I heard shouting at home plate over a called third strike.\""), .direct("What did you see happen between {D} and {V}?", "\"{D} argued the call with {V}, the umpire. When {V} turned to walk away, {DL} struck {V.him} in the face, and {V} went down.\""), .direct("Who else saw it?", "\"Two players were close enough to see it. I took their names, and I wrote the incident report that night.\""), .direct("Where were you standing when the third strike was called?", "\"About thirty feet down the first base line, near the bleachers. I had a clear view of the plate and the area behind it, and I was watching because the call had drawn complaints.\""), .direct("What did the players who saw the blow tell you right afterward?", "\"Two of them said they saw a closed fist hit {V} in the mouth. One was a player from {DL}'s own team, and both gave written statements before they left the field.\""), .direct("What injuries did {V} have when you reached the umpire?", "\"{V} was bleeding from the lip and holding a hand over the mouth. A tooth was loose, and I called deputies and drove {V.him} to urgent care myself.\""), .cross("Was it a push or a punch?", "\"In my judgment it was a punch. I was not standing right there, so I rely on what the two players told me.\""), .cross("{D} says {V} stepped on {D.his} foot. Did you see that?", "\"I did not see it. That is what {DL} told me afterward. It could have happened, but it does not explain a blow to the face.\""), .cross("Did anyone say {V} had been taunting {D}?", "\"I did hear that from one player later, but it was not in my first report. People get heated in these games.\""), .cross("Did you see anyone put a hand on the defendant before the blow?", "\"I did not. I saw {DL} walk to the plate, a short exchange, and then {V} turned to leave. I can't speak to anything that happened before I started watching.\""), .cross("Did you ever see {V} step on the defendant's foot?", "\"No. I was not close enough to see anyone's feet, and nobody told me about it until {DL} mentioned it after the deputies arrived.\"")],
        theory: ("{D} punched an umpire over a called strike.", "A shove after a stepped-on foot."),
        allocution: "\"I lost my temper, and I'm sorry. I disagreed with a called third strike, walked to the plate to talk, and when we got close I pushed back. I coach kids and I'm supposed to set an example. I'll pay for the dental work, and I won't go near an umpire like that again.\"",
        truths: ("The scoreboard camera showed a fist.", "A third player said {V} had been taunting {D}."),
        defendant: [.direct("What happened with {V} after the third strike?", "\"I disagreed with the call and walked to the plate to talk. {V} stepped on my foot as we got close, and I pushed back.\""), .direct("Where did your hands go?", "\"I put my hands out and shoved {V.him} off my foot. It was a quick motion, and I did not plan to hurt {V.him}.\""), .direct("Looking back, how do you feel about what happened?", "\"I'm sorry {V.he} was hurt. I am the coach, and I should be setting an example for the kids who were watching.\""), .direct("Why did you walk to the plate after the called third strike?", "\"I thought the pitch was low and wanted to ask the umpire about it. I've coached this team for four years, and I have talked to umpires before without a problem.\""), .direct("What did {V} say to you when you got there?", "\"Something short and sarcastic about my coaching. I told {V.him} I was only asking about the strike zone, and it escalated from there.\""), .direct("What happened when {V} turned to leave?", "\"I felt a foot come down on mine and I reacted. My hands went out, and I shoved {V.him} away from me.\""), .cross("{V} had a split lip and lost a tooth. Is that from a push?", "\"I do not know exactly how it happened. It was fast. I am sorry about the injury, whatever caused it.\""), .cross("You were the one who walked to the plate, weren't you?", "\"I did. I wanted an explanation. I should have stayed on my side of the line, and I know that.\""), .cross("Two players say they saw a punch. Are they lying?", "\"I don't think they are lying. They saw it from a distance, and it happened fast. I remember it as a push.\""), .cross("The two players who saw this say they saw a fist. Why would they say that if it wasn't true?", "\"They may have seen it from an angle that made it look that way. I know I put my hands out, and I don't think I closed a fist.\""), .cross("{V} lost a tooth. A shove doesn't usually do that, does it?", "\"I don't know how it happened. {V.he} could have hit the backstop or the ground. I only know I'm sorry {V.he} was hurt.\"")],
        openings: ("During a recreation league softball game, an umpire called a third strike. The State will show that {D}, a coach, argued the call and then struck {V} in the face, causing a split lip and a lost tooth.", "This was a pushing match after an umpire stepped on a coach's foot. The defense will show a quick shove that was not a punch, and a coach who regrets what happened."),
        closings: ("Two players saw it, the supervisor wrote it up, and {V} lost a tooth. A coach who strikes an umpire over a called strike has crossed a line that no argument justifies.", "One shove in a heated moment, after {V} stepped on {D}'s foot. The State's own witnesses did not see the beginning. A push is not a punch, and the facts do not support the larger charge."),
        timeline: [(0, "Evening: the called third strike."), (0, "The punch."), (0, "The league supervisor calls deputies.")],
        identified: "The league's incident report.",
        impact: "I lost a tooth, and I can't umpire without my teeth. I've called games for twelve years for a little cash and a lot of love for the sport. I needed dental work I can't afford, and I stayed home from my day job for a week. I just wanted to call a clean game.",
        genders: ["V": .male])

    static let ticketScalper = SmallCases.make(
        key: "story.ticketScalper",
        category: .whiteCollar,
        headlines: ["Facebook Seller Sold Fake Concert Tickets", "Fans Outside Venue Find Tickets Worthless"],
        law: "falsePretenses",
        spec: "Obtained $240 from {V} by falsely representing that {D} was selling genuine concert tickets, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "{V} paid {D} $240 on {DATE} for two concert tickets listed on a Facebook marketplace page. At the venue, the barcodes were rejected as duplicates. A second buyer had the same tickets. {DL} says {D.he} bought the tickets legitimately and never knew they were copies.",
        state: [E(.digital, 3, "The Listing", "{D}'s listing for two tickets at $120 each, sold to {V} and a second buyer."), E(.document, 2, "Payment", "$240 sent to {D}'s account.")],
        defense: [E(.statement, 1, "Bought Tickets", "{DL} says {D.he} bought them from a reseller.")],
        role: "Venue box office manager",
        exam: [.direct("What happened at the gate that evening?", "\"When {V} presented two concert tickets, our scanner rejected the barcodes as duplicates. Someone else had already been admitted using the same codes.\""), .direct("How many people ended up holding the same tickets?", "\"Three buyers came to us with the same two barcodes. Only one set could be valid, and the other two people were turned away.\""), .direct("What did {V} tell you about the purchase?", "\"{V} said $240 was paid to {D} through a social media marketplace page. {V} showed me the messages and the payment record.\""), .direct("How does your scanner treat a ticket the second time it is presented?", "\"It flags it as already used and shows the time and gate of the first scan. Here the first scan had gone through earlier that evening, and {V}'s scan was the second.\""), .direct("How did you confirm that all three buyers held the same barcodes?", "\"I compared the numbers on each set of tickets. They were identical, character for character, down to the row and seat on the printed copy.\""), .direct("What did you tell {V} at the box office?", "\"That I could not admit the family, and that the tickets looked like copies. I gave {V} the number to call to report it to deputies.\""), .cross("{D} may not have known the tickets were copies, isn't that right?", "\"That's possible, but whoever sold the same seats to three people gets the same result. I can only tell you what our scanner showed.\""), .cross("{D} did give one refund, didn't {D.he}?", "\"Eventually, yes, after deputies were called. It did not happen that night, and it did not help the other two buyers.\""), .cross("Can your system tell who created the duplicate copies?", "\"No. It tells us that the barcode was used once already. It does not tell us who made the copies or who sold them.\""), .cross("Is there any way for a buyer to tell a copied ticket from a real one?", "\"Not by looking. A good copy looks the same as the original, and the scanner is the only thing that tells the difference.\""), .cross("Did {D} ever contact the venue about the tickets?", "\"No. The venue never heard from {D.him}, so I can't say what {D.he} knew or intended.\"")],
        theory: ("{D} sold the same tickets to several buyers.", "A reseller who didn't know they were copies."),
        allocution: "\"I'll refund everyone who bought from me. I bought those tickets from a reseller online and believed they were real, and I never would have sold them if I'd known. I'm sorry for the family that drove to the show and got turned away at the gate. I was wrong not to check them more carefully.\"",
        truths: ("{DL}'s phone held a screenshot of the original barcode sent to three people.", "The reseller who sold {DL} the tickets was arrested for the same scheme."),
        defendant: [.direct("Where did you get the tickets you sold?", "\"I bought them from a reseller online. I paid for them and I believed they were real tickets with real barcodes.\""), .direct("Did you know the tickets might be copies?", "\"No. I had no idea. If I had known, I would never have sold them to anyone.\""), .direct("What did you do once you heard about the problem?", "\"I sent a refund to the first buyer when I found out. I felt terrible. I was trying to fix it, and I was embarrassed.\""), .direct("Tell us how you came to have two concert tickets to sell.", "\"A reseller I found online offered a few pairs at a discount, and I bought two pairs. I planned to use one and sell the other.\""), .direct("Why did you list the tickets on a marketplace page?", "\"My plans changed and I could not go. I priced them at $120 each, close to what I paid, so they would sell quickly.\""), .direct("What happened when {V} told you about the gate?", "\"I was shocked. I sent a refund right away and apologized, and I told {V.him} the tickets had come from a reseller.\""), .cross("Three people paid for the same seats. Didn't you notice?", "\"I did not think about it, and I did not keep careful records. That was careless of me, and I admit it.\""), .cross("You sold two tickets for $240. Was that more than you paid?", "\"It was somewhat more, yes. I was trying to make a little money on the sale, and that is not unusual.\""), .cross("Where is the reseller who sold them to you?", "\"I do not know where that person is now. I have the messages, but I can't produce the person, and that hurts my case.\""), .cross("Your phone has a screenshot of the barcode that you sent to three people, doesn't it?", "\"It has a screenshot, yes. I sent it to people who asked to see a ticket before buying. I did not know I was sending the same code more than once.\""), .cross("You listed tickets for sale you hadn't used. What did you do to confirm they were real?", "\"I trusted the reseller. I didn't scan them or call the venue, and I know I should have checked before selling.\"")],
        openings: ("{V} paid $240 for two concert tickets and drove two hours with a six-year-old, only to find that the barcodes had already been used. Three buyers held the same tickets, and all of them came from {D}.", "{D} bought the tickets from a reseller and sold them in good faith. The defense will show someone who had no idea the barcodes were copies and who tried to make it right."),
        closings: ("Three buyers, one set of barcodes, and a family turned away at the gate. Whoever sold the same seats three times took their money. The only question is whether {D} knew it.", "{D} was one link in a chain, buying from someone else and passing the tickets on. {D.He} refunded what was asked. A seller who is fooled is not a thief."),
        timeline: [(-5, "{DL} lists the tickets."), (0, "Concert night: the gate rejects {V}'s tickets."), (2, "{V} reports it to deputies.")],
        identified: "The venue's duplicate scan and {V}'s complaint.",
        impact: "We drove two hours with a six-year-old in the back seat, and he'd talked about nothing else for a month. At the door they scanned our tickets and told us someone else had already used them. I'd paid two hundred forty dollars. We turned around in a parking lot full of other people's smiles.",
        genders: ["D": .male])

    static let cameraSmash = SmallCases.make(
        key: "story.cameraSmash",
        category: .property,
        headlines: ["Neighbor's Doorbell Camera Smashed, Man Charged", "Camera Caught Its Own Destruction"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a doorbell camera, causing damage of $230, on {DATE}.",
        ages: 24...66,
        victim: true,
        summary: "{V}'s doorbell camera, installed after a package theft, was smashed with a hammer on {DATE}. The camera uploaded the last seconds to its cloud: {D}, {V}'s neighbor, swinging the hammer. {DL} says the camera pointed into {D.his} bedroom window.",
        state: [E(.video, 3, "Cloud Upload", "{D} swings a hammer at the camera and the feed ends."), E(.document, 2, "Receipt", "$230 for the camera.")],
        defense: [E(.document, 2, "Angle", "Photos show the camera angled across the property line.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you asked to investigate?", "\"{V} reported that a doorbell camera, installed after a package theft, had been smashed with a hammer on {DATE}. The camera cost $230.\""), .direct("What did the camera's cloud upload show?", "\"In its last seconds it uploaded {D}, {V}'s neighbor, swinging a hammer at the lens, and then the feed ends.\""), .direct("How did {V} learn who did it?", "\"{V} checked the cloud account that evening and saw the video. {V} recognized {DL} right away because they live next door.\""), .direct("Had there been trouble between them?", "\"Yes. {DL} had texted before, telling {V} to take it down or {DL} would take it down. {V} showed me that text.\""), .direct("What did {D} say when you spoke?", "\"{D.He} admitted breaking it and said it was aimed into {D.his} bedroom window. {D.He} said {D.he} had asked {V} to point it away.\""), .direct("What was the damage?", "\"The camera body was cracked and the lens shattered. It was a total loss, with no way to repair it, and {V} had to buy a new one.\""), .cross("Isn't it true {V} had moved the camera two days earlier?", "\"{V} told me it was moved, yes. {V} said the new angle was to cover the porch and driveway better, and denied aiming it at any window.\""), .cross("Do photos show the camera angled across the property line?", "\"Yes. {D.He} provided photos showing the camera angled across the line toward {D.his} side. I can't tell from them exactly what it could see.\""), .cross("Did you ever look through the camera's view?", "\"I viewed its recorded frames. They show part of {DL}'s yard and the edge of the house, though not a clear view into a window.\""), .cross("Did the defendant go to the sheriff before breaking the camera?", "\"Not to my knowledge. There's no report from {D.him} about the camera before it was smashed.\""), .cross("Did the defendant try to run or deny it?", "\"No. {D.He} admitted it directly and didn't argue about the video. {D.He} was upset about the privacy complaint.\"")],
        theory: ("{D} smashed a neighbor's camera with a hammer.", "A man protecting his privacy."),
        allocution: "\"I should have talked to {V.him} face to face instead of swinging a hammer. That camera was pointed right at my bedroom window, and I asked more than once for it to be moved. I lost my patience. I'll replace the camera, and I'm sorry for what it cost.\"",
        truths: ("{DL} texted 'take it down or I'll take it down.'", "{V}'s camera had been moved two days earlier to face {DL}'s bedroom."),
        defendant: [.direct("Why did you smash the camera?", "\"It had been turned to face my bedroom window. I asked my neighbor to move it, and the next day it was still pointed there.\""), .direct("What did you do first?", "\"I texted {V} and asked politely. When that didn't work I sent a stronger text saying to take it down or I'd take it down myself.\""), .direct("How did you feel about the camera?", "\"Violated. My bedroom window faces that side of the house, and I couldn't relax knowing a lens was aimed at it.\""), .direct("Did you swing the hammer yourself?", "\"Yes. I did it that evening, and I'll admit it. I lost patience after days of being ignored.\""), .direct("Did you try any other approach?", "\"I thought about calling the sheriff, but I figured they'd say it's a neighbor dispute. Looking back, I should have tried that first.\""), .direct("Would you pay for the camera?", "\"I'd pay for the camera if the court asks me to. I shouldn't have destroyed it, even if I was upset.\""), .cross("You sent a text warning you would take it down?", "\"I did. It was a clear warning, and I followed through when nothing changed. I know that's on me.\""), .cross("You took a hammer to a neighbor's property?", "\"Yes, I did. I'm not proud of it, and I know it was the wrong way to solve it.\""), .cross("Photos show the camera angled across the line, but not into your window clearly, correct?", "\"The photos show the angle across the property line. Whether it could see the window is something I believed, and I can't prove it from the pictures.\""), .cross("Did you ask a deputy or a landlord to look at the angle?", "\"No. I went straight to the text and then the hammer. I should have had someone else look at it.\""), .cross("The camera was installed after packages were stolen from {V}'s porch?", "\"I'm aware of that, and I understand why {V} wanted a camera. I just didn't think it should point into my house.\"")],
        openings: ("{V} put up a doorbell camera after a package theft, and {D}, the next-door neighbor, swung a hammer into it. The camera's last seconds in the cloud show {DL}, and {DL}'s own text had warned {V} to take it down or {DL} would.", "{V} had moved the camera two days earlier and it pointed across the property line toward {D}'s bedroom window. The defense says {DL} acted out of fear for {D.his} privacy, and the State must prove a malicious intent."),
        closings: ("The cloud video shows {D}, the text shows the threat, and a $230 camera was destroyed. A neighbor's complaint about a camera angle did not give {DL} permission to take a hammer to it.", "The camera had been moved to face {D}'s bedroom window and {D.he} asked politely first. This was a privacy dispute that boiled over, and the State has not shown that {D.he} acted with the malice the charge requires."),
        timeline: [(-2, "{V} moves the camera."), (0, "Evening: {DL} swings the hammer."), (0, "{V} reviews the cloud upload.")],
        identified: "{V}'s cloud upload.",
        impact: "I installed that camera after packages kept disappearing from my porch, and it was the only thing between me and a repeat. It was smashed with a hammer, and I watched the last seconds on my phone from the cloud. Now I look over my shoulder when I come home. All I wanted was to feel safe.",
        genders: ["D": .male])

    static let rideshareRunner = SmallCases.make(
        key: "story.rideshareRunner",
        category: .property,
        headlines: ["Passenger Ran From Rideshare Without Paying $38 Fare", "Driver's Dash Camera Shows Man Bolting"],
        law: "misdLarceny",
        spec: "Stole $38 in transportation services from {V}, a rideshare driver, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "{V}, a rideshare driver, took {D} 14 miles on {DATE} at 12:40 a.m. At the drop-off, {DL} said {D.he} was getting cash and ran into a house. The fare was $38. {V}'s dash camera recorded the exchange. {DL} says {D.he} had a card that was declined and meant to return with cash.",
        state: [E(.video, 3, "Dash Camera", "{D} says 'I'll be right back' and runs; the driver waits twenty minutes."), E(.document, 2, "Fare Record", "$38 for 14 miles; the card on file was declined.")],
        defense: [E(.statement, 1, "Declined Card", "{DL} says {D.his} card was declined and {D.he} went for cash.")],
        role: "Rideshare driver",
        exam: [.direct("Tell us about the ride on that night.", "\"I picked up {D} and drove about fourteen miles. It was 12:40 a.m. when the ride started, and the fare came to $38 when we arrived.\""), .direct("What did {D} say at the drop-off?", "\"{D.He} said, 'I'll be right back,' that cash was needed from inside, then got out and ran into the house. My dash camera recorded the whole exchange.\""), .direct("How long did you wait?", "\"About twenty minutes. I knocked, and I called through the app. Nobody came back out, and I finally left with no payment.\""), .direct("How did the ride start, and where did you pick up the defendant?", "\"A request came through the app at 12:40 a.m. from a bar on the east side. {D.He} got in, gave the address of a house fourteen miles away, and said little during the drive.\""), .direct("What did the defendant do when you reached the address?", "\"{D.He} said the card might not go through and that cash was inside. {D.He} told me, 'I'll be right back,' got out, and ran up the walk and into the house.\""), .direct("What did you do during the twenty minutes you waited?", "\"I knocked on the door, called through it, and phoned the app's support line. At 1:25 I called deputies because no one had come out.\""), .cross("Wasn't the defendant's card declined?", "\"It was declined after the ride, according to the app. During the ride I had no way to know that, so I accepted the pickup.\""), .cross("Did the defendant ever return to pay?", "\"No. I never saw {D.him} again that night and I never got the fare. I reported it to the sheriff's office.\""), .cross("Could the defendant have been looking for cash in good faith?", "\"It is possible, but twenty minutes is a long time to look for cash. At some point I had to assume it was not happening.\""), .cross("The fare was $38. Did you try to charge the card again?", "\"The app tried to charge it automatically and the card was declined. I do not control that process, so I could not try another one.\""), .cross("Did anyone at the house say the defendant was inside?", "\"A roommate answered once and said {D.he} was in the shower. I can't say whether that was true or only a way to make me leave.\"")],
        theory: ("{D} rode 14 miles and ran from the fare.", "A declined card and a trip for cash."),
        allocution: "\"I'll pay the fare and the tip, and I'm sorry for leaving that night. My card was declined when the app tried to charge it, and I panicked and went inside for cash. I never meant to take something I didn't pay for. A driver works hard for every dollar, and I know that.\"",
        truths: ("{DL} had left unpaid fares at two other rides that month.", "{DL}'s roommate answered the door and said {D.he} was in the shower."),
        defendant: [.direct("Did you mean to pay for the ride?", "\"Yes, I did. I took the ride believing I would pay, and I had every intention of settling the fare.\""), .direct("What happened with your card?", "\"It was declined when the app tried to charge the fare. I did not know it would be, and I panicked when I saw the notice.\""), .direct("Why did you go into the house?", "\"I went to find cash. I said I'd be right back and I meant it. I looked for the money, but I couldn't find enough quickly.\""), .direct("Tell the jury why you took a rideshare that night.", "\"My car was in the shop, and I had been out with friends. It was late, and a rideshare was the easiest way to get home.\""), .direct("When did you realize your card might not work?", "\"As we were pulling up. I looked at my banking app and saw a hold I hadn't expected. I told the driver I had cash inside.\""), .direct("What did you do inside the house for those twenty minutes?", "\"I was looking for cash and then I hid in the bathroom out of embarrassment. I should have gone straight back out and told the driver the card had been declined.\""), .cross("You were inside for twenty minutes. What were you doing?", "\"I was searching for cash and then I was hiding, honestly. I was embarrassed that I could not pay, and I didn't know how to go back.\""), .cross("You never came back out, did you?", "\"No. I own that. I let embarrassment win and stayed inside, and I know that looks like running.\""), .cross("Why say 'I'll be right back' and then run?", "\"I did not run in the sense you mean. I walked fast because I was upset. I regret how it all looks.\""), .cross("The driver knocked and called through the door for twenty minutes. Why didn't you answer?", "\"I could hear it, and I didn't know what to do. I should have gone out and paid the fare on my card later, and I regret not doing that.\""), .cross("This was not the first unpaid ride in your recent history, was it?", "\"I've had a couple of declined cards before. I never meant to avoid paying, and I've never done this on purpose.\"")],
        openings: ("A fourteen-mile rideshare trip at 12:40 in the morning ended with a $38 fare that was never paid. The driver's dash camera recorded {D} saying 'I'll be right back' and running into a house.", "{D}'s card was declined and {D.he} went inside to find cash. The defense will show an embarrassed passenger who meant to pay, not someone who planned to cheat a driver."),
        closings: ("Fourteen miles, twenty minutes of waiting, and a promise to be right back. The driver was never paid. A person who takes a ride knowing the card might fail has cheated the driver.", "A declined card is not a plan to steal. {D} went to look for cash and was too embarrassed to return. The State has not shown {DL} intended from the start to avoid paying."),
        timeline: [(0, "12:40 a.m.: the ride begins."), (0, "1:05 a.m.: {DL} runs into the house."), (0, "1:25 a.m.: {V} calls deputies.")],
        identified: "{V}'s dash camera and the ride record.",
        impact: "I waited twenty minutes on a night when I needed that fare, and nobody came back out. It was past midnight on a dark road, and I'd driven fourteen miles to get there. My dash camera shows every second. I drive for a living, and a thirty-eight dollar fare isn't small to me.",
        genders: ["D": .male])

    static let wheelBootCut = SmallCases.make(
        key: "story.wheelBootCut",
        category: .property,
        headlines: ["Man Cut Off Wheel Boot With Bolt Cutters", "Towing Company Says $450 in Damage"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a wheel immobilizer, causing damage of $450, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "A towing company put a boot on {D}'s car for parking in a private lot without a permit on {DATE}. {D.He} cut the boot off with bolt cutters and drove away. The boot, worth $450, was ruined. {DL} says the lot had no signs and the boot was unlawful.",
        state: [E(.video, 3, "Lot Camera", "{D} cuts the boot with bolt cutters and drives off."), E(.physical, 2, "Cut Boot", "A wheel boot cut through the center, $450.")],
        defense: [E(.statement, 1, "No Signs", "{DL} says there were no parking signs at the entrance.")],
        role: "Towing company owner",
        exam: [.direct("What does your lot camera show?", "\"It shows {D} kneeling at the wheel with bolt cutters, cutting the boot off, and then driving the car out of the lot.\""), .direct("Why was the boot on {D}'s car?", "\"The car was parked in our private lot without a permit. We put a boot on it, as we do for every unauthorized car.\""), .direct("What was the boot worth?", "\"The boot is worth $450. After it was cut, it was ruined and cannot be used again.\""), .direct("How do you notify drivers about the parking rules at that lot?", "\"There is a sign on the building at the corner of the lot, and a permit is required on weekdays. We also put a notice on windshields when a car has been there too long.\""), .direct("When did the boot go on, and who put it on?", "\"About noon, by one of my drivers. The car had been there since early morning without a permit, and we had a complaint from the business that owns the lot.\""), .direct("What did you do after you saw the lot camera footage?", "\"I called the sheriff's office and sent the video. The boot was ruined, and I had to replace it before using it on the next car.\""), .cross("Was there a sign at the entrance of that lot?", "\"The signs are on the building, not at the entrance. I have heard the complaint that they are not easy to see from the driveway.\""), .cross("Did the defendant pay the parking fee before the boot was cut?", "\"No. {D.He} did not pay anything. We had asked for $200 to remove the boot, and {D.he} cut it off instead.\""), .cross("Has the city ever questioned your signage?", "\"Not to my knowledge before this. A city inspector looked at the lot after this incident, and I did not receive a citation that I recall.\""), .cross("A notice under the wiper was the only warning before the boot went on, wasn't it?", "\"Mostly. We leave a notice under the wiper when a car sits without a permit, and the boot goes on after that.\""), .cross("How much do you charge to remove a boot, and was that posted?", "\"Two hundred dollars. The fee is posted on the boot itself, which is how a driver finds out what it costs.\"")],
        theory: ("{D} cut a boot off with bolt cutters.", "A driver angry at an unlawful boot."),
        allocution: "\"I lost my temper, and I'll pay for the boot. I couldn't come up with two hundred dollars to get it taken off, and I had to be at work. I didn't see any signs when I pulled into that lot. That doesn't justify cutting it, and I'm sorry for the loss to the company.\"",
        truths: ("{DL} owned the bolt cutters and brought them to the lot.", "The towing company had no signs at the entrance, a city inspector confirmed."),
        defendant: [.direct("Why did you cut the boot?", "\"I could not pay $200 to remove it, and I had to get to work. I was angry and I was stuck, and I made a bad decision.\""), .direct("Were you aware you were parking in a private lot?", "\"I did not see any signs when I pulled in. If there was a sign, I did not notice it, and nobody told me.\""), .direct("Why did you have bolt cutters with you?", "\"I carry them in my car. They are for work and for locks on my own things, and I did not buy them for that day.\""), .direct("How long did you plan to park at that lot?", "\"About an hour. I was running an errand next door and pulled in because it was the nearest open spot.\""), .direct("What did you see when you came back to your car?", "\"A boot on the front wheel and a note with a phone number. I called, and the person said it would be two hundred dollars cash to remove it.\""), .direct("Why didn't you pay the fee and dispute it later?", "\"I didn't have that much on me. I also felt it was wrong, since I never saw a sign, and I was angry.\""), .cross("You brought bolt cutters to a boot, didn't you?", "\"They were in my car already. I did use them, and I will not deny that. I took them out when I was angry.\""), .cross("You drove off without paying anything. Isn't that taking the law into your own hands?", "\"I suppose it is. I was frustrated, and I thought the boot was unfair. I should have called someone.\""), .cross("The boot cost $450. Do you plan to pay for it?", "\"I would like to work something out. I cannot afford it right now, but I did not mean to destroy anyone's property for fun.\""), .cross("You cut a boot worth $450 and drove away. Weren't there other ways to handle that?", "\"Yes. I could have called the sheriff's office or the property owner, and I should have. I was upset and I did something I regret.\""), .cross("You say you didn't see signs. Did you walk around the lot to look for any?", "\"No. I pulled in and parked, and I did not check. If I had, I would have seen the one on the building.\"")],
        openings: ("A towing company booted {D}'s car for parking in a private lot without a permit. The lot camera shows {DL} cutting the boot off with bolt cutters and driving away, leaving a ruined $450 boot behind.", "The lot had no signs at the entrance, and {D} was stuck with a $200 fee and a job to get to. The defense will show a driver angry at an unfair boot, not someone out to destroy property."),
        closings: ("The video shows bolt cutters, a cut boot, and a car driven away. Whether or not you like the fee, destroying someone else's equipment is not the way to settle it.", "Without clear signs at the entrance, {D} had no warning that the lot was restricted. A driver who cuts a boot to get to work acted out of desperation, not malice."),
        timeline: [(0, "Midday: the boot goes on."), (0, "Afternoon: {DL} cuts it off."), (0, "The owner sees the camera.")],
        identified: "The tow company's lot camera.",
        impact: "A boot costs my company four hundred fifty dollars, and once it's cut, it can't be recovered. We buy them one at a time and we put them out where cars are parked without a permit. It takes a crew of two to replace it. I'm sorry to say it, but this happens more than people realize.",
        genders: ["D": .male])

    static let noonBurglary = SmallCases.make(
        key: "story.noonBurglary",
        category: .property,
        headlines: ["Daytime Break-In Empties Jewelry Box While Family Was at Work", "Neighbor's Doorbell Camera Shows Man at Back Door"],
        law: "feloniousBE",
        threshold: 6,
        spec: "Broke and entered a dwelling house of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "{V} came home from work on {DATE} to find the back door kicked in and a jewelry box and a laptop gone. A neighbor's doorbell camera showed a man in a green hooded sweatshirt at the back gate at 11:20 a.m. A pawn shop took in a ring matching {V}'s description that afternoon from {D}. {DL} says {D.he} bought the ring from a friend and was never at the house.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on a ticket for a ring matching {V}'s description, 4:40 p.m. the same day."), E(.video, 3, "Doorbell Camera", "A man in a green hooded sweatshirt opens the back gate at 11:20 a.m.")],
        defense: [E(.statement, 1, "Friend", "{DL} says a friend sold {D.him} the ring that morning.")],
        role: "Sheriff's detective",
        exam: [.direct("How did the burglar get into the house?", "\"The back door was kicked in. The frame was split near the lock, and there was a footprint on the lower panel.\""), .direct("What was taken?", "\"A jewelry box and a laptop. The owner, {V}, came home from work and called us right away.\""), .direct("How did {D} become a suspect?", "\"A neighbor's doorbell camera showed a person in a green hooded sweatshirt at the back gate at 11:20 a.m. Then a pawn ticket showed a ring matching {V}'s description pawned that afternoon by {D}.\""), .direct("What was the condition of the house when you arrived?", "\"The back door frame was splintered where it had been kicked in, and a muddy boot print was on the door. Drawers in the bedroom were open and a jewelry box was gone.\""), .direct("What do the pawn shop records show?", "\"A ring matching {V}'s description was pawned at 4:40 p.m. the same day. The pawn ticket carries {D.his} ID and the time stamp, and the shop photographed the ring.\""), .direct("What did {V} say about the ring?", "\"It was a family ring with a small garnet. {V} described it before I saw the pawn ticket and recognized it from the shop's photograph.\""), .cross("The face isn't visible on the doorbell video, is it?", "\"No. The hood hides the face. I can tell you the sweatshirt color and the build, not who was wearing it.\""), .cross("{D} says a friend sold {D.him} the ring, doesn't {D.he}?", "\"That is {DL}'s account, yes. {DL} would not give me the friend's name, and I had no way of checking the story.\""), .cross("{D} pawned the ring under {D.his} own name, didn't {D.he}?", "\"Yes, with a valid ID. That is something I noted, because it is not what most burglars do with stolen property.\""), .cross("Did you recover the laptop or the jewelry box from the defendant?", "\"No. Neither was found at {D.his} home or at the pawn shop, and only the ring turned up.\""), .cross("Did anyone see the defendant near {V}'s house on the day of the burglary?", "\"No one placed {DL} there. The neighbor's camera shows someone in a hood, but I can't say who it was from the video.\"")],
        defenseRole: "Defendant's coworker",
        defenseExam: [.direct("Where was {D} at 11 a.m. that day?", "\"{D} was at work with me, on the floor, until about noon. We work the same shift and I saw {D.him} that morning.\""), .direct("How can you be sure about the time?", "\"I remember because we had a delivery come in around 11, and {D.he} helped unload. It was a busy morning.\""), .direct("Did you see the defendant leave early?", "\"No. {D.He} was there until noon, when we both took lunch. I did not see {D.him} leave before that.\""), .direct("What do you do for work, and how do you know the defendant?", "\"I work on the same floor at the warehouse. We started within a month of each other, and I see {DF} most of my shifts.\""), .direct("What was the defendant doing that morning, as far as you saw?", "\"Loading pallets near my station. We took a break about ten, and {D.he} was still there when the next delivery arrived at eleven.\""), .direct("Did anything unusual happen at the warehouse that morning?", "\"A truck was late and we were short two people, so nobody could have walked off without it being noticed.\""), .cross("Did you personally clock the defendant in?", "\"No. I saw {D.him} on the floor, but I was not the one at the time clock. I can't say who punched what.\""), .cross("You and the defendant are friends, aren't you?", "\"We are friendly, yes. That does not change what I saw, but I understand why the State asks.\""), .cross("Could you have been mistaken about the time?", "\"I suppose I could be off by a little, but not by a couple of hours. The delivery fixes it in my mind.\""), .cross("You have never been inside {V}'s house, have you?", "\"No. I have never been to that house and I only know about the burglary from what {DF} told me.\""), .cross("Where was the time clock?", "\"By the break room door, next to the time cards. I could see it from where I worked most of the night.\"")],
        theory: ("{D} kicked in a back door and pawned a ring that afternoon.", "A pawn ticket from a friend and a coworker's alibi."),
        allocution: "\"I never went to that house, and I'm sorry for what the owner went through. I know how it feels to come home and find your door kicked in. I was at work that morning with my coworkers, and I have a ring from a friend that I never should have taken to a pawn shop without asking more.\"",
        truths: ("A green sweatshirt was found in {DL}'s trunk with glass fibers from the back door.", "The time clock was punched by a coworker for {DL}, a supervisor later admitted."),
        defendant: [.direct("Did you break into that house?", "\"No. I was never at that house. I have never been to that street, and I did not take anything.\""), .direct("Where were you at 11 that morning?", "\"I was at work. I was on the floor all morning with my coworkers and I did not leave until noon.\""), .direct("Where did the ring come from?", "\"I bought it from a friend around noon, for a fair price. I pawned it later that afternoon, because I needed money.\""), .direct("What time did you start work that day?", "\"At 7 a.m. I was on the loading floor all morning, and I wouldn't have been able to leave without a supervisor noticing.\""), .direct("Tell the jury how you ended up with the ring.", "\"A friend I trust sold it to me in the parking lot around noon for sixty dollars. I thought it was an old ring and I liked it.\""), .direct("Why did you pawn it that afternoon?", "\"I needed cash for rent. I took it to the pawn shop after work and showed my real ID because I had nothing to hide.\""), .cross("The ring was pawned at 4:40 p.m. Why did you wait?", "\"I was busy until the afternoon. I did not hurry. I did not think there was any reason to rush.\""), .cross("You won't give the friend's name. Why not?", "\"It is hard for me to name someone, and I'm not sure I can find the person.\""), .cross("You used your own ID at the pawn shop. Is that smart for stolen property?", "\"That is the point. I did not think the ring was stolen. I had nothing to hide, so I used my own name.\""), .cross("You say you can't name the friend. Isn't that convenient?", "\"It is not convenient for me. I would give a name if I could, but we lost touch and I don't have a number.\""), .cross("Someone in a green hooded sweatshirt was on camera that morning. Do you own one?", "\"I own a lot of sweatshirts, and one is green. I wore it to work that day, and I wasn't at that house.\"")],
        openings: ("{V} came home to a kicked-in back door and a missing jewelry box and laptop. A doorbell camera shows a green-hooded figure at the gate, and that same afternoon {D} pawned a ring matching {V}'s description.", "Listen for the defense evidence, which will show that {D} was at work at 11 a.m., that no face appears on the doorbell video, and that {D.he} pawned the ring openly, under {D.his} own name."),
        closings: ("A kicked door, a green hooded sweatshirt on camera, and a pawn ticket for the missing ring that same afternoon. {D} cannot name the friend who supposedly sold it, and that silence speaks.", "No one can see a face on that video, and a coworker puts {D} at work. A pawn ticket under a real name is not what a burglar leaves behind. The State has not closed that gap."),
        timeline: [(0, "11:20 a.m.: a man opens the back gate."), (0, "4:40 p.m.: {DL} pawns the ring."), (0, "5:30 p.m.: {V} comes home to the broken door.")],
        identified: "The pawn shop's ticket and a neighbor's camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mitigating: ["The defendant has a positive employment history and is gainfully employed", "The defendant has accepted responsibility"],
        mood: .wantsConviction,
        impact: "My mother's ring was in that box, and she wore it for fifty years. I came home from work and found the back door kicked in and my laptop gone. I haven't felt safe in my own house since. I check the lock three times before I go to bed.",
        genders: ["D": .male])

    static let bankNoteRobbery = SmallCases.make(
        key: "story.bankNoteRobbery",
        category: .robbery,
        headlines: ["Man Slides Demand Note to Teller, Leaves With $2,100", "Bank Camera Captures Robbery by Note"],
        law: "commonLawRobbery",
        threshold: 7,
        spec: "Took $2,100 in United States currency from the person and presence of {V}, a bank teller, by putting {V.him} in fear, on {DATE}.",
        ages: 22...55,
        victim: true,
        summary: "A man in a ball cap handed {V}, a bank teller, a note on {DATE} that said 'Put the money in the bag, no dye pack, no alarm.' {V} handed over $2,100 and triggered a silent alarm. The man walked out. Deputies stopped {D} three blocks away with a cap and $1,640 in bills. {DL} says {D.he} had cashed a paycheck at another bank and has never been inside this branch.",
        state: [E(.video, 3, "Bank Camera", "A man in a ball cap hands a note to the teller and walks out with a bag."), E(.physical, 3, "The Cap and Cash", "A ball cap matching the video and $1,640 in bills, including bait bills.", .search)],
        defense: [E(.document, 2, "Paycheck", "A $1,200 paycheck cashed at a check-cashing store the same morning.")],
        role: "Bank teller",
        exam: [.direct("What happened at your window at about 10:15 a.m. on {DATE}?", "\"A customer in a ball cap stepped up and slid me a note. It said, Put the money in the bag, no dye pack, no alarm.\""), .direct("What did you do after reading it?", "\"I put cash in the bag, $2,100 in all, and I pressed the silent alarm with my knee while I was counting it out.\""), .direct("What did the person look like?", "\"Medium build, ball cap pulled low, and a jacket zipped up. The cap hid most of the forehead and the eyes, and I couldn't tell the age very well.\""), .direct("How did the person behave?", "\"Calm and quiet, almost businesslike. There was no weapon shown, no shouting, and the person took the bag and walked out the front door.\""), .direct("What happened with the alarm?", "\"It triggered at 10:18 and the sheriff's office was notified. I locked my drawer, told my manager, and waited for the deputies.\""), .direct("What did you learn about the money later?", "\"Deputies told me they'd found $1,640 on someone three blocks away, and that two of the bills matched the bait bills from my drawer.\""), .cross("Isn't it true you did not see the person's whole face?", "\"That's right. The cap brim cast a shadow over the eyes, and I only saw the lower half. I couldn't pick a face from a lineup.\""), .cross("Did you see the person come in or leave on foot?", "\"I saw them walk in and out the front door. I didn't see which way they went once they got outside the glass.\""), .cross("How sure are you that the cap deputies found is the same one?", "\"It looked similar in color and style, but ball caps are common. I wouldn't swear it was the same cap, only that it resembled it.\""), .cross("Did you recognize the voice, if any words were spoken?", "\"The person said almost nothing, maybe thanks at the end. It was a low voice and I couldn't tie it to anyone.\""), .cross("How many bait bills were in the stack?", "\"I'm told two. The bank records the serials, so those were identifiable, but I didn't see the stop and can't say where they were found.\"")],
        defenseRole: "Check-cashing clerk",
        defenseExam: [.direct("What do you do at the check-cashing store?", "\"I'm a clerk at a check-cashing store. I verify the person's ID, count out the cash, and give the customer a receipt for every transaction.\""), .direct("Did {D} come in on the morning of {DATE}?", "\"Yes, {D} came in that morning and cashed a $1,200 paycheck. I counted out the bills myself and handed them over.\""), .direct("What denominations did you give the defendant?", "\"Mostly twenties and some tens and fives, the kind of bills we keep in the drawer for payroll checks. We don't hand out hundreds.\""), .direct("What time was this?", "\"I'd say a little before ten. I can't give the exact minute, but the receipt has a printed time and it was before the robbery.\""), .direct("Do you keep a record of such transactions?", "\"Yes, every check we cash gets a receipt with a stamp, and our register keeps a log. That receipt is what I gave {D.him}.\""), .direct("Did you notice anything unusual about the defendant?", "\"No. {D.He} was relaxed, made small talk, and left. Nothing about the visit made me think twice.\""), .cross("You can't say where the defendant went after leaving your store?", "\"No. I only saw {DF} walk out the door. I can't speak to what {DF} did afterward or what time {DF} reached the parking lot.\""), .cross("Isn't it true bills of the same denomination are common in the area?", "\"They are. Lots of stores and banks hand out twenties and tens, so you can't tie a pile of those to any one source.\""), .cross("You don't know what other cash the defendant had that morning, do you?", "\"I don't. I only know what I paid out, $1,200, and whatever {DF} carried in beforehand is something I couldn't see.\""), .cross("How far is your store from the bank branch?", "\"About fifteen minutes on foot, a little less by car. It's not very far, so someone could go from one to the other.\""), .cross("Do you remember every customer?", "\"Not all of them. I remember {D.he} because of the amount, but I couldn't swear to the exact bills or their serial numbers.\"")],
        theory: ("{D} handed a teller a demand note and took $2,100.", "A paycheck cashed and bills in his pocket."),
        allocution: "\"I was out of money and out of options that week, and I'm sorry for the trouble I've brought here. I had cashed a paycheck that morning and I had bills in my pocket and a cap on my head. I never walked into that bank and I never handed a teller a note. I'm sorry {V.he} was frightened.\"",
        truths: ("Two bait bills from the bank's drawer were in {DL}'s pocket.", "The check-cashing receipt showed {DL} had received $1,200 in bills that morning, the same denominations."),
        defendant: [.direct("Where were you at 10:15 that morning?", "\"Cashing a paycheck. I'd stopped at a check-cashing store earlier in the morning and picked up my pay in bills.\""), .direct("Have you ever been inside that bank branch?", "\"Never. I don't bank there and I have no account anywhere near that block. I wouldn't know where the teller windows are.\""), .direct("How much cash did you have when the deputies stopped you?", "\"About $1,640. My paycheck was $1,200, and the rest was cash I had from earlier in the week for bills.\""), .direct("Why were you three blocks from the bank?", "\"I was walking to my car after the check-cashing store. It's a short walk, and I parked in a lot on that side of the street.\""), .direct("Why were you wearing a ball cap?", "\"I wear one most days. It's one of three I own, and the deputies took the one I had on.\""), .direct("What did you tell the deputies?", "\"That I'd just cashed a check and had nothing to do with any robbery. I gave them the name of the check-cashing store.\""), .cross("You had $1,640 in your pocket three blocks from a robbery?", "\"Yes. I know how it looks, but that's the money I had, and part of it was from the check I'd just cashed.\""), .cross("Two bait bills were in your pocket, weren't they?", "\"The deputy told me that. I can't explain how bills from that bank's drawer got in my hand, except that bills move around between people.\""), .cross("The robber got $2,100 and you had $1,640?", "\"I do. I can't tell you where the rest of that money might be, and I don't know anything about it.\""), .cross("You can't prove the cap you wore wasn't the one on camera?", "\"It's a common style and I wear it often. I know it matches the video in a general way, but a thousand people wear that kind of cap.\""), .cross("Isn't a paycheck of $1,200 in cash rather unusual?", "\"I cash checks that way because I don't have a bank account. It's how I've always gotten paid, and the store has a receipt.\"")],
        openings: ("At 10:15 on {DATE} a customer in a ball cap passed a teller a note demanding money with no dye pack and no alarm, and walked out with $2,100. Twenty-five minutes later, deputies stopped {D} three blocks away with a matching cap and $1,640 in bills, two of them bait bills from the teller's drawer.", "{D} cashed a $1,200 paycheck at a check-cashing store that morning and has never set foot in that branch. The defense says the teller never saw the robber's face, and a cap and cash are what thousands of people carry."),
        closings: ("A note, a bag, $2,100, and a silent alarm, followed by a stop three blocks away with a cap matching the video and bills from the bank's own drawer. {D} had both the cap and the money, and the bait bills tie it to this branch.", "The teller saw half a face under a cap and recognizes no voice. A check-cashing receipt explains $1,200 of {D}'s cash, and the State's own bait bills move from hand to hand like any other bill, which leaves reasonable doubt."),
        timeline: [(0, "10:15 a.m.: the note is passed."), (0, "10:18 a.m.: the silent alarm."), (0, "10:40 a.m.: deputies stop {DL} three blocks away.")],
        identified: "The bank's alarm and a deputy's stop.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mitigating: ["The defendant has accepted responsibility"],
        impact: "I still feel my heartbeat when someone hands me a folded paper. The man's note said no dye pack and no alarm, and I did what I was trained to do and slid the bills across. My hands shook for an hour afterward. I went home and couldn't eat.",
        genders: ["D": .male, "V": .female])

    static let cocaineBagStop = SmallCases.make(
        key: "story.cocaineBagStop",
        category: .drugs,
        headlines: ["Deputies Find Packaged Cocaine in Driver's Console", "Driver Says Bags Were Left by Passenger"],
        law: "pwisd",
        threshold: 7,
        spec: "Possessed with intent to sell or deliver cocaine, a Schedule II controlled substance, on {DATE}.",
        ages: 21...50,
        victim: false,
        summary: "A deputy stopped {D} for a headlight on {DATE} and smelled marijuana. In the console were fourteen small bags of white powder, a digital scale, and $720 in small bills. The lab found cocaine in all fourteen, about 9 grams total. {DL} says the bags belonged to a passenger who got out minutes earlier and that the cash was {D.his} rent money.",
        state: [E(.physical, 3, "Fourteen Bags", "Fourteen bags with cocaine, about 9 grams total, in the console.", .search), E(.physical, 2, "Scale and Cash", "A digital scale and $720 in small bills.", .search)],
        defense: [E(.statement, 2, "Passenger", "{D} says a passenger left minutes before the stop.")],
        role: "Sheriff's narcotics detective",
        exam: [.direct("Why did you stop {D}'s car?", "\"A patrol deputy stopped it at about 5:05 p.m. on {DATE} for a broken headlight. I came to assist when the deputy smelled marijuana.\""), .direct("What did the search turn up?", "\"In the console we found fourteen small baggies of white powder, a digital scale, and $720 in small bills, mostly fives, tens, and twenties.\""), .direct("What did the lab find?", "\"All fourteen bags tested positive for cocaine, about nine grams in total. Each bag held a little over half a gram, a typical street-sale amount.\""), .direct("What about the scale and the cash?", "\"The scale had white residue on the tray, and the bills were folded in small bundles. That packaging and quantity is consistent with sales, not personal use.\""), .direct("What did the defendant say at the roadside?", "\"{D} said the bags belonged to a passenger who had gotten out minutes earlier, and that the cash was rent money.\""), .direct("What did you find on the defendant's phone?", "\"Text messages quoting prices per bag, with several recent contacts asking about amounts. I read them from the phone after it was seized.\""), .cross("Isn't it true you did not find any drugs on the defendant's person?", "\"Correct. Nothing was found in {D.his} pockets. Everything was in the console between the seats, within reach of both seats.\""), .cross("Were any fingerprints taken from the bags?", "\"We did not request prints. They weren't tested, so I can't tell you whose fingers touched them.\""), .cross("Was there a passenger in the car earlier?", "\"A gas station camera shows a passenger leaving the car with a duffel at 4:55, ten minutes before the stop. I can't tell who that person is.\""), .cross("Is $720 in small bills proof of drug sales?", "\"Not by itself. Many people carry cash. I rely on the scale, the bags, and the texts in combination.\""), .cross("Did the marijuana smell lead to any marijuana being found?", "\"No marijuana was found. The smell was what justified the search, and I can't explain where it came from.\"")],
        defenseRole: "Defendant's landlord",
        defenseExam: [.direct("What is your relationship to {D}?", "\"I'm {D}'s landlord. {D.He} rents a unit from me, and I collect the rent each month, usually the first week.\""), .direct("How does the defendant pay the rent?", "\"In cash, in small bills, delivered to me in an envelope. {D.He} has done it that way for as long as {D.he} has lived there.\""), .direct("How much is the rent?", "\"$720 a month. That's what the unit costs, and it's exactly what {D.he} has brought me month after month.\""), .direct("Was rent due around the date of the stop?", "\"Yes, it was due that week. {D.He} had told me earlier that {D.he} would drop it off after work that day.\""), .direct("Has the defendant ever been late?", "\"Once or twice, by a few days, but always paid. I have no complaints about {DF} as a tenant.\""), .direct("Have you ever seen anything suspicious at the defendant's unit?", "\"Not that I've noticed. It's a quiet place, and I haven't had complaints from other tenants about visitors.\""), .cross("You weren't in the car with the defendant that day, were you?", "\"No. I wasn't there. I only know that rent was due and that {D.he} usually pays in cash.\""), .cross("You can't say whether the $720 in the console was the rent?", "\"I can't. I can only say it's the same amount as the rent. I never saw it until after the stop.\""), .cross("Did you receive the rent that week?", "\"Not that week, because the deputies had the money. {D.He} paid me later, by a different method.\""), .cross("Do you know what the defendant does for work?", "\"In general, I know {D.he} has a job and gets paid regularly. I don't know the details or how steady it is.\""), .cross("Do you know anything about the defendant's phone texts or contacts?", "\"No. I don't look at my tenants' phones and I have no idea about that.\"")],
        theory: ("{D} had packaged cocaine and a scale in the console.", "A passenger's bags and rent money."),
        allocution: "\"I made a mistake letting someone ride in my car that I barely knew. I was holding for a friend, and I should have asked what was in that console. I'm sorry for letting it get this far. I have a job and a family, and I'm asking the court to remember that.\"",
        truths: ("{DL}'s phone held texts quoting prices per bag.", "A camera at the gas station showed the passenger leaving the car with a duffel at 4:55."),
        defendant: [.direct("Whose drugs were in that console?", "\"Not mine. A passenger had been riding with me earlier and got out of the car minutes before I was stopped.\""), .direct("Who was the passenger?", "\"A casual acquaintance who asked for a ride. I knew the name but not much else about the person, and I haven't seen that person since.\""), .direct("What was the cash for?", "\"Rent. My landlord takes it in cash, and I'd just gotten paid. I had the $720 in the console on the way to pay.\""), .direct("Why did you keep rent money in the console?", "\"I didn't want it in my pocket where I might lose it. It was in an envelope and I kept it where I could reach it.\""), .direct("What did you think when the deputy found the bags?", "\"I was stunned. I told the deputy right away that they weren't mine and that the passenger must have left them behind.\""), .direct("How do you explain the scale?", "\"I never saw a scale. If one was in my console, the passenger left it, because I don't have any use for one.\""), .cross("The texts on your phone quoted prices per bag, correct?", "\"There are texts with prices on my phone. I can't explain them without getting into things I don't want to talk about, but I wasn't selling that night.\""), .cross("You knew the passenger had a duffel when they got out?", "\"I saw a bag, but I didn't look inside. I didn't think it was my business.\""), .cross("Why would a passenger leave fourteen bags behind?", "\"I don't know. I thought maybe they forgot, or that they hid them in my console without telling me.\""), .cross("Did you look in the console before the stop?", "\"No. I opened it to get my rent envelope, and I think I saw the envelope and nothing else. I didn't dig around.\""), .cross("You didn't mention the passenger's name to the deputies, did you?", "\"I gave the first name I knew. I don't have a number or an address, and that makes my story hard to check.\"")],
        openings: ("On {DATE}, deputies stopped {D} for a headlight and found fourteen bags of cocaine, a digital scale, and $720 in small bills in the console. The lab found about nine grams in all, and {D.his} phone held texts quoting prices per bag.", "The drugs belonged to a passenger who got out minutes before the stop, and the $720 was {D}'s rent, paid in cash every month. The defense says the State found a console shared by two people and cannot prove whose bags they were."),
        closings: ("Fourteen bags, a scale with residue, $720 in small bills, and texts that quote prices per bag, all in the console within {D}'s reach. Packaged for sale and found in {D.his} car, that is possession with intent to sell.", "A passenger left the car with a duffel ten minutes before the stop, no drugs were found on {D}, and the landlord confirms the rent is $720 in cash every month. A shared console and a quiet tenant do not prove whose cocaine it was."),
        timeline: [(0, "Late afternoon: the passenger leaves the car."), (0, "5:05 p.m.: the stop for a headlight."), (0, "5:20 p.m.: the console search.")],
        identified: "A traffic stop.",
        aggravating: ["The offense involved sale or delivery"],
        mitigating: ["The defendant has accepted responsibility"],
        doctrines: ["searchSeizure", "burdenOfProof"],
        genders: ["D": .male])

    static let sellPillsAtWork = SmallCases.make(
        key: "story.sellPillsAtWork",
        category: .drugs,
        headlines: ["Warehouse Worker Sold Oxycodone to Coworkers", "Undercover Coworker Bought Pills in Break Room"],
        law: "deliverSchedII",
        threshold: 6,
        spec: "Delivered oxycodone, a Schedule II controlled substance, to another person, on {DATE}.",
        ages: 24...58,
        victim: false,
        summary: "A warehouse worker told a supervisor that {D} sold oxycodone in the break room. Deputies set up a controlled buy on {DATE}: the worker, wearing a wire, bought six pills for $90 from {DL}. {DL} says the worker asked for a favor and {D.he} gave pills from {D.his} own prescription without charging.",
        state: [E(.digital, 3, "Wire Recording", "'Six for ninety.' 'Okay.' The sound of pills in a bag."), E(.physical, 3, "The Pills", "Six oxycodone tablets bought in the buy, identified by the lab.")],
        defense: [E(.document, 2, "Prescription", "{D}'s prescription for 60 oxycodone, filled a week earlier.")],
        role: "Sheriff's narcotics detective",
        exam: [.direct("How was the controlled buy arranged?", "\"A coworker told a supervisor that {D} sold oxycodone in the break room. The coworker agreed to wear a wire, and we set up the buy at the warehouse.\""), .direct("What was said on the recording?", "\"The recording captures {DL} saying 'six for ninety.' It is clear and it is the price for six pills.\""), .direct("What did {D} hand over?", "\"Six oxycodone pills in exchange for $90. We recovered the pills from the coworker right after the buy and sent them to the lab.\""), .direct("What did you do to prepare the coworker for the controlled buy?", "\"We searched the coworker and the vehicle, confirmed there were no pills or cash on hand, and gave $90 in marked bills. A wire recorder was taped under the shirt.\""), .direct("Where did the buy take place, and how long did it last?", "\"In the warehouse break room during the lunch break. The recording runs about ninety seconds from the greeting to the hand-off.\""), .direct("What did you do with the pills afterward?", "\"I met the coworker in the parking lot, collected the wire and the pills, and sealed the pills in an evidence bag. They went to the lab that afternoon.\""), .cross("Could those pills have come from the defendant's own prescription?", "\"The lab can confirm they are oxycodone. It cannot tell us whose prescription they came from, so I can't rule that out.\""), .cross("{D} didn't know the coworker was wearing a wire, did {D.he}?", "\"No, {D.he} did not know. That is how a controlled buy works, and we did not tell {D.he} before the exchange.\""), .cross("Did the coworker have a history of asking the defendant for pills?", "\"I heard that later. At the time, I was working from what the coworker told us, and I did not do a deep check.\""), .cross("Did you search the defendant after the buy, or recover the marked bills?", "\"No. We did not detain {DL} that day, so I can't tell you where the marked bills went.\""), .cross("The coworker had a reason to cooperate. What was it?", "\"The coworker had been caught with pills at work and was offered a way to resolve it by helping us. I can't say what else the coworker may have wanted.\"")],
        defenseRole: "Pharmacist",
        defenseExam: [.direct("Did {D} have a prescription for oxycodone?", "\"Yes. {D} had a prescription for 60 tablets, filled at our pharmacy. I can see it in the records.\""), .direct("Was it a valid prescription?", "\"It was written by a licensed physician and filled in the usual way. There is nothing unusual in how it was filled.\""), .direct("Do those pills look like what the prescription would produce?", "\"They are consistent with that kind of product, yes. I can't say for certain which bottle the pills came from.\""), .direct("What are you licensed to do, and how do you know the defendant?", "\"I'm a pharmacist at the store where {D.he} fills prescriptions. I filled {D.his} prescription for sixty tablets about a week before the date in question.\""), .direct("What does the label say about who may take the medication?", "\"It says the medication is for the patient named on the label only. The counseling sheet also says not to share it.\""), .direct("How do the tablets from the controlled buy compare with those in the defendant's prescription?", "\"They are the same strength and manufacturer markings as the tablets we dispense for that prescription, which is consistent with, but not proof of, the same bottle.\""), .cross("Does a prescription allow the defendant to give or sell pills to others?", "\"No. It is only for the person it is written for. Sharing pills is not permitted.\""), .cross("Can you tell from the pills whether they came from the defendant's bottle?", "\"No. I cannot match a pill to a specific bottle from what I was shown.\""), .cross("How many tablets would be left from the prescription by that date?", "\"That depends on how {DF} took them. I cannot say how many should have been left on that day.\""), .cross("Did you ever see the pills being handed to a coworker?", "\"No. I know only what we dispensed and what the lab says the tablets are.\""), .cross("Would a pharmacist agree that giving tablets to someone else violates the patient's instructions?", "\"Yes. It is not how the medication is meant to be used, whether money changes hands or not.\"")],
        theory: ("{D} sold six oxycodone to a coworker for $90.", "A prescription shared as a favor."),
        allocution: "\"I shouldn't have given pills away at work, and I'm sorry. A coworker asked me for a favor and I gave a few from my own prescription, with no price on it. I didn't think about the risk to anyone. I've learned my lesson, and I'll never share medicine again.\"",
        truths: ("{DL}'s phone held texts offering pills 'for a price.'", "The coworker had been asking {DL} for pills for weeks and was the one who set up the buy."),
        defendant: [.direct("Did you sell pills to your coworker?", "\"I gave a few pills to a coworker who asked for a favor. They were from my own prescription, and I did not mean it as a sale.\""), .direct("Why did you take money?", "\"The coworker insisted on handing me the cash. I did not count it, and I did not set a price. I just wanted it to be over.\""), .direct("Why did the recording say 'six for ninety'?", "\"That is what the coworker said, not me. I did not argue about it, and maybe I own that.\""), .direct("Explain to the jury why you have a prescription for oxycodone.", "\"I had a back injury at work and the doctor prescribed sixty tablets after surgery. I took them as directed and kept the rest.\""), .direct("How did your coworker ask you for pills?", "\"Over a few weeks, mostly in passing. The coworker said the pain was bad and a doctor's visit was weeks away.\""), .direct("What happened in the break room?", "\"The coworker pushed a roll of bills into my hand and said it was for gas. I handed over some tablets and didn't think about what it looked like.\""), .cross("You took $90 for six pills, didn't you?", "\"I took the money, yes. I did not count it, and I know that sounds strange, but I did not think of it as a sale.\""), .cross("You were willing to hand over pills at work. Isn't that dealing?", "\"I know it was wrong. I was trying to be nice to a coworker and I did not think it through.\""), .cross("Why would a coworker set you up?", "\"I do not know. The coworker had been asking me for a while, and I finally gave in.\""), .cross("The recording says 'six for ninety.' Whose voice says that?", "\"It was the coworker's voice, not mine. I think the coworker was setting up the sentence so it would sound like a sale.\""), .cross("If it was only a favor, why did you take money?", "\"I should not have. I didn't count it, and I thought pushing it back would make a scene in front of other people.\"")],
        openings: ("A coworker reported that {D} sold oxycodone in the warehouse break room. On a controlled buy, {D.he} handed over six pills for $90 on a recording that says 'six for ninety.'", "{D} has a valid prescription and shared a few pills as a favor to a coworker who kept asking. The defense will show a favor, not a business."),
        closings: ("A wire, a price, six pills, and $90. 'Six for ninety' is not how people talk about a gift. The prescription does not give {D} the right to sell.", "The pills came from {D}'s own prescription, and the coworker pushed for them for weeks and set up the buy. This was a mistake, not a drug operation."),
        timeline: [(-10, "{DL} fills the prescription."), (0, "Lunch break: the controlled buy."), (0, "The detective collects the wire and the pills.")],
        identified: "A coworker's report and a controlled buy.",
        aggravating: ["The offense involved sale or delivery"],
        mitigating: ["The defendant has a positive employment history and is gainfully employed", "The defendant has accepted responsibility"])

    static let domesticChoke = SmallCases.make(
        key: "story.domesticChoke",
        category: .violent,
        headlines: ["Woman Says Boyfriend Choked Her During Argument", "911 Call Captures Struggle in Kitchen"],
        law: "strangulation",
        threshold: 7,
        spec: "Assaulted {V} and inflicted physical injury by strangulation, on {DATE}.",
        ages: 22...50,
        victim: true,
        summary: "{V} called 911 on {DATE} and whispered that {V.his} boyfriend was 'choking me.' Deputies arrived to find red marks on {V}'s neck and a broken lamp. {D} said {V} had been drinking and hit {D.him} first. {V} told deputies {DL} grabbed {V.him} by the throat against the kitchen counter for several seconds. {DL} says {V} scratched {D.his} own neck.",
        state: [E(.digital, 3, "911 Recording", "{V}: 'He's choking me,' followed by a thud and the line cutting off."), E(.physical, 3, "Photographs", "Red marks and fingertip bruising on {V}'s neck, photographed at 11:40 p.m.")],
        defense: [E(.statement, 1, "Scratches", "{DL} says the scratches on {D.his} own arm show {V} attacked first.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did you first learn of this incident?", "\"Dispatch relayed a 911 call at about 11:05 p.m. on {DATE} in which {V} whispered that {V.his} partner was choking {V.him}. I responded and arrived around 11:15.\""), .direct("What did you see when you arrived?", "\"{V} had red marks on the neck, was crying, and was holding a towel. A lamp lay broken on the kitchen floor and a chair was knocked over.\""), .direct("What did {V} tell you?", "\"{V} said {D} grabbed {V.him} by the throat against the kitchen counter for several seconds and that {V} had trouble getting air.\""), .direct("What did you notice about {D}?", "\"{D.He} had scratches on the arm and was agitated but cooperative. I photographed them, and I photographed {V}'s neck later at 11:40.\""), .direct("What did the photographs show?", "\"Red marks and fingertip-like bruising on the sides of {V}'s neck. A medical exam afterward noted small red spots in the eyes, called petechiae.\""), .direct("What did you find in the kitchen that told you a struggle had happened?", "\"A broken lamp on the floor and a chair pushed out of place. There was also a necklace chain on the counter, which a doctor later discussed.\""), .cross("Isn't it true the defendant also had scratches?", "\"Yes, scratches on the forearm. I couldn't tell you from looking whether they came from a struggle or something else.\""), .cross("Did you see the fight yourself?", "\"No. I arrived ten minutes after the call, and everything I know came from the people there and the scene.\""), .cross("Was {V} intoxicated?", "\"{V} had been drinking, according to both of them. I smelled alcohol on {V}'s breath, but {V} was able to speak clearly and give a coherent account.\""), .cross("Could a necklace chain explain the marks?", "\"A doctor suggested a chain could leave similar marks. I did see a broken chain on the floor, though I can't say it caused them.\""), .cross("Did the 911 call record any words from the defendant?", "\"No. It records {V}'s whisper, a thud, and the line cutting off. I can't hear any words from {DL} on it.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("How do you know {D} and {V}?", "\"I'm the next-door neighbor. Our kitchen walls are thin, and I've lived beside them for a few years, so I know their routines.\""), .direct("What did you hear that night?", "\"Around eleven I heard raised voices from both of them. There was yelling back and forth for a few minutes and then a loud crash.\""), .direct("Whose voices did you hear?", "\"Both. {V} was shouting loudly and so was {D}. I couldn't make out words, but neither was quiet.\""), .direct("What did you hear after the crash?", "\"A thump and then quiet for a bit, followed by what sounded like crying. After that the deputies arrived outside.\""), .direct("Have you heard fights from that house before?", "\"Occasionally, mostly arguments about drinking. It was always loud talk from both sides and never anything that made me call anyone.\""), .direct("What did you see of the defendant afterward?", "\"{D.He} came out on the porch before the deputies came in. {D.He} looked upset and was holding an arm, and said, I didn't do anything.\""), .cross("You didn't see inside the kitchen, did you?", "\"No, I only heard it through the wall. I couldn't tell you what either person was doing with their hands.\""), .cross("You can't say who started the shouting?", "\"I can't. By the time I paid attention it was both voices at once, so I couldn't separate who began it.\""), .cross("You didn't hear {V} say anything about choking?", "\"No. I heard crying afterward, but nothing I could understand about choking. The wall isn't that clear.\""), .cross("Did you call 911 yourself?", "\"No. I was on the fence about it and then the deputies were already outside, so I never made a call.\""), .cross("You're friendly with the defendant, aren't you?", "\"I've known {DF} longer than I've known {V}. I try to be fair, but yes, I like {DF} as a neighbor.\"")],
        theory: ("{D} grabbed {V} by the throat and cut off {V.his} breath.", "A mutual fight that {V} started."),
        allocution: "\"I'm sorry for what happened that night. We were arguing about drinking, and it got out of hand. I never put my hands around {V}'s neck, but I know {V.he} was scared and hurt. I should have walked out of the kitchen sooner. I want both of us to get help.\"",
        truths: ("{V}'s medical exam showed petechiae consistent with strangulation.", "The neck marks were from a necklace chain that broke in the fight, a doctor suggested."),
        defendant: [.direct("What happened in the kitchen that night?", "\"We argued about drinking. {V} had been drinking all evening, and it got heated. {V} hit me first, in the chest, and I pushed back.\""), .direct("Did you put your hands on {V}'s throat?", "\"No. I grabbed at {V}'s wrists to stop the hitting. I never put my hands around {V}'s neck and never squeezed anything.\""), .direct("How did the lamp get broken?", "\"It got knocked off the counter in the struggle. We were both moving around the kitchen, and it went over.\""), .direct("Where did your scratches come from?", "\"From {V}. {V} was clawing at my arm when I grabbed the wrists. I took photos on my phone and showed them to the deputy.\""), .direct("What did you do after the argument?", "\"I stepped back and tried to calm {V} down. I had no idea {V} had called 911 until the deputies knocked on the door.\""), .direct("How do you explain the marks on {V}'s neck?", "\"I think {V} scratched at {V.his} own neck, or a necklace chain broke in the fight. I don't know for sure, but I didn't choke anyone.\""), .cross("You and {V} were both physical that night?", "\"Yes. It turned into a shoving match, and I'm not claiming I was calm. I just didn't choke {V}.\""), .cross("{V} whispered to 911 that you were choking {V.him}?", "\"That's what I'm told. I can't explain why {V} would say it, except that {V} was angry and drunk and scared of what we'd done.\""), .cross("A medical exam found petechiae, didn't it?", "\"Yes, that was in the report. I'm not a doctor, and I only know that I didn't squeeze {V}'s throat.\""), .cross("You've had arguments with {V} before?", "\"We've had some, like most couples. I've never put hands on {V} before this, and the neighbors would say the same.\""), .cross("You pushed {V} against the counter?", "\"I may have backed {V} against it while grabbing the wrists. It was a few seconds, and I know that sounds bad.\"")],
        openings: ("At 11:05 p.m. {V} whispered into a phone that {D} was choking {V.him}, and the line went dead after a thud. Deputies found red marks on {V}'s neck, a broken lamp, and a victim who said {DL} pinned {V.him} against the kitchen counter by the throat.", "This was a loud fight between two people, with {V} drinking and swinging first, and {D} grabbing wrists to stop it. The defense says the neck marks have another explanation, and the State cannot prove {DL} ever touched {V}'s throat."),
        closings: ("The 911 recording, the red marks and fingertip bruising, and the small spots in the eyes all fit the same account. {V} told the dispatcher, the deputy, and the doctor that {D} grabbed {V.him} by the throat, and the evidence agrees.", "Two people were shouting, a lamp broke, and a necklace chain lay on the floor. {D} had scratches from the fight too, and nobody saw a hand on {V}'s throat, which is where reasonable doubt begins."),
        timeline: [(0, "10:50 p.m.: the argument in the kitchen."), (0, "11:05 p.m.: {V} calls 911."), (0, "11:15 p.m.: deputies arrive.")],
        identified: "{V}'s 911 call.",
        aggravating: ["The offense involved a victim in a domestic relationship"],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .wantsConviction,
        impact: "I couldn't swallow properly for a week, and I still flinch when someone reaches near my neck. I whispered into the phone from the kitchen because I was afraid to be heard. There were red marks that I covered with a scarf at work. I want to feel safe in my own home again.",
        genders: ["D": .male, "V": .female])

    static let phoneSnatch = SmallCases.make(
        key: "story.phoneSnatch",
        category: .robbery,
        headlines: ["Man Snatched Phone From Woman's Hand at Bus Stop", "Robbery Charge After Phone Grab and Shove"],
        law: "commonLawRobbery",
        threshold: 6,
        spec: "Took a cellular telephone valued at $780 from the person of {V} by violence, on {DATE}.",
        ages: 18...35,
        victim: true,
        summary: "{V} was texting at a bus stop on {DATE} when a man grabbed {V}'s phone, shoved {V.him} hard enough to knock {V.him} down, and ran. A bus camera caught the grab. Two blocks away, a deputy stopped {D}, who matched the description and had a phone in each pocket. {DL} says one was {D.his} and the other was a friend's.",
        state: [E(.video, 3, "Bus Camera", "A man grabs the phone, pushes {V}, and runs west."), E(.physical, 3, "The Phone", "{V}'s phone, with a cracked case, in {D}'s jacket.", .search)],
        defense: [E(.statement, 1, "Friend's Phone", "{DL} says a friend gave {D.him} the phone to sell.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find when you stopped {D}?", "\"Two phones, one in each pocket. {D} fit the description given by {V} and was walking two blocks from the bus stop.\""), .direct("Whose was the second phone?", "\"One of them was {V}'s phone, with a cracked case. {V} identified it when I showed it, and it unlocked with {V}'s code.\""), .direct("What injuries did {V} have?", "\"Scraped palms and a bruised knee from being knocked to the ground. {V} did not need an ambulance.\""), .direct("What was the description that went out over the radio?", "\"A slim person in a gray jacket and dark pants, running west from the bus stop on the avenue. It came about five minutes after the grab, from the camera footage.\""), .direct("Where exactly did you stop {D}, and what was {D} doing?", "\"Two blocks west, on the sidewalk by a laundromat. {D.He} was walking at a normal pace with both hands in the jacket pockets.\""), .direct("Did {V} get the phone back?", "\"Yes, the next day, after the lab photographed it. {V.He} signed for it at the station.\""), .cross("{D} told you a friend gave {D.him} one of the phones, didn't {D.he}?", "\"That was the account. When I asked for the friend's name, I got nothing I could follow up on.\""), .cross("{D} was walking, not running, when you stopped {D.him}, right?", "\"Yes, {D.he} was walking at a normal pace. {D.He} did not run or resist when I came up.\""), .cross("The bus camera doesn't show a face clearly, does it?", "\"The video shows the grab and the shove, but the face is hard to see. I based the stop on clothing and location.\""), .cross("Did the person in the bus camera video have a limp or a particular way of moving?", "\"The video is short and I can't say. I did not see {DL} walk far enough to compare.\""), .cross("Did you find the clothing from the video in the defendant's possession?", "\"A gray jacket, yes. But gray jackets are common, and I can't say it was the one on the video.\"")],
        defenseRole: "Defendant's cousin",
        defenseExam: [.direct("Did {D} tell you about a phone from a friend?", "\"Yes, a few days before. {D} said a friend gave {D.him} an extra phone to use.\""), .direct("How did the defendant seem when you spoke about it?", "\"Casual. {D.He} did not seem to be hiding anything. That was my impression at the time.\""), .direct("Does the defendant usually carry more than one phone?", "\"Not that I know of. This was the only time I heard about a second one.\""), .direct("What is your relationship to the defendant?", "\"I'm {DF}'s cousin. We grew up together and I see {DF} most weeks.\""), .direct("Who was the friend the defendant said gave {D.him} the phone?", "\"{D.He} didn't give me a name. {D.He} only said it was a friend who needed help selling it.\""), .direct("Did the defendant seem nervous or secretive about it?", "\"No. {D.He} told me about it casually, over dinner, and showed me the phone.\""), .cross("Did you ever see the friend who supposedly gave the defendant the phone?", "\"No. I only heard about it from {D.him}, and I have no way to confirm it.\""), .cross("Did you see the phone before that day?", "\"I don't think I did. I can't say whether {D.he} had it a week ago or since that day.\""), .cross("Do you know anything about what happened at the bus stop?", "\"No, I wasn't there. All I know is what {D.he} told me earlier.\""), .cross("Have you known the defendant to buy or sell phones before?", "\"Once, a couple of years ago. It was a used phone, and as far as I know it was all above board.\""), .cross("Does the defendant match the limp that a doctor noted on the person in the video?", "\"No. {D.He} walks normally and has never had a limp that I have seen. I noticed the difference when the case was explained to me.\""), .cross("Why would the defendant be holding someone else's phone?", "\"{DF} told me a friend asked {DF} to sell it. I cannot say whether that is true, and I did not see the exchange myself.\"")],
        theory: ("{D} grabbed a phone, shoved a woman, and ran.", "A phone from a friend and a description that fits many."),
        allocution: "\"I was not at that bus stop, and I never touched anyone, and I'm sorry that {V} was hurt. I had two phones in my pockets, and one was a friend's old spare that I should have looked at closer. I needed money that week and I made a poor choice about that phone, but that's all.\"",
        truths: ("{DL}'s jacket matched the video and had a scrape on the sleeve.", "The man in the video had a limp that {DL} doesn't have, a physician later noted."),
        defendant: [.direct("Did you grab {V}'s phone?", "\"No. I was not at that bus stop. I did not touch anyone and I did not run from anywhere.\""), .direct("Where did the second phone come from?", "\"A friend gave it to me. I did not look closely at it, and I thought it was just an old spare.\""), .direct("Where were you coming from when the deputy stopped you?", "\"I was walking home. I was minding my own business and I had no idea why I was being stopped.\""), .direct("Where were you before the deputy stopped you?", "\"I'd come from a friend's place and was walking home, about a mile. I hadn't been near the bus stop on the avenue that evening.\""), .direct("What are the two phones in your pockets?", "\"One is mine, with my own number. The other came from a friend who told me to try to sell it and keep a small cut.\""), .direct("What did you say to the deputy when you were stopped?", "\"I told the deputy I had two phones and explained why. I offered to call my friend, but the call went to voicemail.\""), .cross("The second phone had a cracked case. Didn't you wonder whose it was?", "\"It was like that when I got it. I did not think much of it.\""), .cross("You had two phones in your pockets two blocks from a snatching, didn't you?", "\"I did. I know how that looks, and I'm sorry that a stranger got hurt. But it was not me.\""), .cross("Can you name the friend?", "\"I can name someone, but I can't produce that person. I know that makes it hard to believe me.\""), .cross("You had a phone you were supposed to sell and you didn't ask where it came from?", "\"I figured it was a used phone. I didn't ask because I trusted my friend, and I know that wasn't smart.\""), .cross("You match the description and were two blocks from the scene ten minutes later. Is that a coincidence?", "\"It is. I live in that direction, and many people who walk home in that area wear gray.\"")],
        openings: ("{V} was texting at a bus stop when someone shoved {V.him} down, grabbed the phone, and ran. Two blocks away, a deputy found {D}, who matched the description and had two phones in {D.his} pockets, one of them {V}'s.", "By the end of this trial, the proof will show that the bus camera never clearly shows a face, that {D} was walking calmly, and that a phone from a friend does not make {DL} a thief."),
        closings: ("A grab on camera, a shove to the pavement, and then {D} two blocks away with the victim's cracked phone in a pocket. A story about a friend who cannot be found does not change that.", "The camera shows a grab but no clear face, and {D} was simply walking home. A phone from a friend is not proof of a robbery, and the State must do more than point to a description."),
        timeline: [(0, "6:20 p.m.: the grab at the bus stop."), (0, "6:25 p.m.: deputies broadcast a description."), (0, "6:35 p.m.: a deputy stops {DL}.")],
        identified: "The bus camera and a deputy's stop.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mitigating: ["The defendant has accepted responsibility"],
        impact: "I limped for a week after being shoved to the pavement, and I don't use my phone at bus stops anymore. It was a normal evening and I was answering a text from my sister. I felt a hand on the phone and then the ground. I take a different route home now.",
        genders: ["D": .male, "V": .female])

    static let payrollCheckForge = SmallCases.make(
        key: "story.payrollCheckForge",
        category: .whiteCollar,
        headlines: ["Bookkeeper Forged Boss's Signature on Eleven Checks", "Employer Finds $9,400 Missing From Payroll Account"],
        law: "forgery",
        threshold: 6,
        spec: "Forged eleven checks totaling $9,400, falsely making the signature of {V}, with intent to defraud, on {DATE}.",
        ages: 28...62,
        victim: true,
        summary: "{V} noticed on {DATE} that {V.his} payroll account was $9,400 short. Eleven checks had been written to {D}, the part-time bookkeeper, over four months, each with {V}'s signature. A handwriting examiner said {V}'s signature was forged. {DL} says {V} had authorized a signature stamp and told {D.him} to pay {D.himself} 'what we owe you.'",
        state: [E(.document, 3, "The Checks", "Eleven checks to {D}, signed 'ML,' totaling $9,400."), E(.forensic, 3, "Handwriting Exam", "'Probably written by' {D}; {V}'s signature is not genuine.")],
        defense: [E(.statement, 2, "Stamp", "{DL} says {V} had a signature stamp and told {D.him} to use it.")],
        role: "Forensic document examiner",
        exam: [.direct("What did you examine in this case?", "\"I examined eleven checks written to {D} over four months, each with a signature that appears to be {V}'s. I compared them with known samples.\""), .direct("What did you conclude?", "\"The signatures on the checks are not {V}'s. The strokes are drawn slowly and the pen pressure patterns differ from {V}'s normal signing.\""), .direct("Whose handwriting do they resemble?", "\"Probably {DL}'s. 'Probably' is the highest level I can give without a stamp or a confession to compare against.\""), .direct("What materials did you receive to examine?", "\"Eleven original checks, known signature samples from {V} taken from other documents, and a set of writing samples provided by {DL}. I examined everything under magnification.\""), .direct("What features of the signatures led you to your opinion?", "\"The pen pressure and the slow, careful connecting strokes did not match {V}'s fluid signature. The forged signatures show hesitation at the first letter, which is typical of a copy.\""), .direct("What is the difference between a stamp and a handwritten signature?", "\"A stamp leaves a uniform ink impression with no variation in pressure. These checks show pen strokes, with ink pooling at the starts and ends.\""), .cross("A signature stamp could produce marks like these, couldn't it?", "\"Not these. A stamp leaves a uniform impression, and these show variable pressure, so they were written by hand.\""), .cross("{V} may have authorized the payments, correct?", "\"Authorization is not something I can judge. I can only tell you who likely made the signatures, not whether {V} approved the payments.\""), .cross("How certain is your opinion?", "\"It is a professional opinion, not a certainty. I have limits, and I state them plainly in my report.\""), .cross("Your opinion is only 'probably.' Why not a definite conclusion?", "\"Because the writing samples were limited and the signatures were short. 'Probably' is the opinion my profession allows in that situation.\""), .cross("Could someone have been practicing {V}'s signature with {V}'s knowledge?", "\"I cannot rule out that someone else wrote them or that {V} allowed it. I can only tell you whose hand the writing resembles.\"")],
        defenseRole: "Office assistant",
        defenseExam: [.direct("Did {V} keep a signature stamp in the office?", "\"Yes, in the top drawer of the desk. I saw it used many times for routine checks.\""), .direct("Who had access to it?", "\"{V} and the bookkeeper both did. It was not locked, and I saw {D} use it more than once.\""), .direct("Did {V} and {D} talk about pay?", "\"They talked about it often. I did not hear every conversation, but I know there were discussions about what was owed.\""), .direct("What was your job at the office, and how long did you work there?", "\"I was the office assistant for two years. I answered phones, filed, and helped {V} with scheduling.\""), .direct("Where was the signature stamp kept?", "\"In the top drawer of the front desk, which was not locked. Anyone who worked in the office could use it.\""), .direct("Did you ever see the defendant use the stamp?", "\"Yes, on routine vendor checks. It happened a few times a month, usually when {V} was out.\""), .cross("Did you see the particular checks being signed?", "\"No. I saw the stamp in use at other times, not these specific checks.\""), .cross("Is it normal for a bookkeeper to pay {D.himself} without written approval?", "\"No. I would expect something in writing for that.\""), .cross("Did you ever see checks written to the defendant being stamped?", "\"No. I did not see those checks being signed, so I can't say whether a stamp or a pen was used.\""), .cross("Did you ever hear {V} authorize the defendant to pay {D.himself}?", "\"No. I never heard that, and I would remember something like that.\""), .cross("Did you ever see the defendant practice a signature on paper?", "\"No. I never saw that. I saw {D.him} at the front desk with the books, and I did not look at what was written in the margins.\""), .cross("Did {V} ever put the pay approval in writing?", "\"Not that I recall. {V} usually said things aloud and expected them to be remembered, which is how overtime was handled in that office.\"")],
        theory: ("{D} forged {V}'s signature to pay {D.himself} $9,400.", "A bookkeeper with a stamp and an oral authorization."),
        allocution: "\"I took what I thought I was owed, and I was wrong to do it the way I did. I used the signature stamp that I was authorized to use, and I understood {V} told me to pay myself what the office owed me. I should have gotten it in writing.\"",
        truths: ("{DL}'s phone held a note, 'practice the ML signature.'", "{V} had approved overtime verbally and never put it in writing, an accountant confirmed."),
        defendant: [.direct("Did you sign those checks?", "\"I used the signature stamp on them. I did not forge anything by hand.\""), .direct("Did {V} know about the payments?", "\"Yes. I told {V.him}, and {V} said to pay myself what the office owed me. It was a spoken agreement.\""), .direct("How much were you owed?", "\"I was owed for overtime and some unpaid hours. I believed those checks covered what the office owed me.\""), .direct("Describe your job and how you were paid.", "\"I did the books part time, about twenty hours a week, plus extra hours at month end. I was supposed to be paid weekly, but {V} often paid late.\""), .direct("Describe the signature stamp in your own words.", "\"It sat in the top drawer of the desk. {V} told me to use it when {V.he} was out of town to keep payroll moving.\""), .direct("What did {V} say about your pay?", "\"That the office owed me for unpaid hours and I should pay myself what we owe you. I took that to mean I could write the checks.\""), .cross("The examiner says the signatures were written by hand. Do you disagree?", "\"I disagree, because I know I used the stamp. I can't explain the examiner's finding, and I can't prove it.\""), .cross("$9,400 over four months is a lot of overtime. Can you show it?", "\"I do not have every record, but I kept notes of hours. It is what I believed I was owed.\""), .cross("Did you put {V}'s approval in writing?", "\"No. It was spoken, and I now know that was a mistake. I should have asked for something on paper.\""), .cross("Why didn't you get {V}'s authorization in writing?", "\"I wish I had. We worked informally and I trusted {V}, so I didn't think I needed anything on paper.\""), .cross("Eleven checks over four months is a lot to write to yourself. Did you tell anyone besides {V}?", "\"No. I thought it was between {V} and me, and I kept the entries in the books so it wasn't hidden.\"")],
        openings: ("Over four months, eleven checks totaling $9,400 were written to {D}, the part-time bookkeeper, each bearing {V}'s signature. A handwriting examiner will tell you those signatures were forged.", "{D} was told to pay {D.himself} what the office owed and used a signature stamp {V} kept in the drawer. The defense will show an approval that was spoken and never written down."),
        closings: ("Eleven checks, $9,400, and a forensic examiner who says the signatures were handwritten, not stamped. Paying yourself from the payroll account with a forged signature is theft and forgery.", "A spoken instruction, a stamp in an unlocked drawer, and wages {D} believed were owed. The State must prove forgery and intent to defraud, and a messy office is not the same as a crime."),
        timeline: [(-120, "The first forged check."), (-30, "The tenth check."), (0, "{V} reviews the account and calls deputies.")],
        identified: "{V}'s account review.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mitigating: ["The defendant has made substantial or full restitution"],
        impact: "That was our payroll for the next two employees, and I had to cover it out of my own savings. Eleven checks were written to the bookkeeper with my signature on them, and I never signed any of them. I trusted this person with my books, and I feel sick about it.")

    static let dopeHouseTrailer = SmallCases.make(
        key: "story.dopeHouseTrailer",
        category: .drugs,
        headlines: ["Neighbors Complain About Trailer With Constant Traffic", "Search Warrant at Trailer Finds Pills and Scales"],
        law: "maintainingDwelling",
        threshold: 6,
        spec: "Knowingly kept and maintained a dwelling used for keeping and selling controlled substances, on {DATE}.",
        ages: 24...58,
        victim: false,
        summary: "After months of neighbors' complaints about cars stopping at {D}'s trailer for two minutes at all hours, deputies searched it on {DATE} with a warrant. They found 41 oxycodone pills in a cereal box, a scale, $1,100 in cash, and a notebook of names and numbers. {DL} says {D.he} let people crash there and had no idea what they kept in the kitchen.",
        state: [E(.physical, 3, "Pills and Scale", "41 oxycodone pills in a cereal box and a digital scale.", .search), E(.document, 3, "Ledger", "A notebook of first names and numbers, with entries like 'T: 3 x 30 = $90.'", .search)],
        defense: [E(.statement, 2, "Crashing", "{DL} says several people stayed at the trailer and the kitchen was shared.")],
        role: "Sheriff's narcotics detective",
        exam: [.direct("What led your unit to {D}'s trailer?", "\"Neighbors had complained for about sixty days that cars stopped at the trailer for two minutes at all hours. We started surveillance two weeks before the search.\""), .direct("What did surveillance show?", "\"Short visits at all hours, a car pulling up, someone going inside for a couple of minutes, and the car leaving. Dozens of those over fourteen days.\""), .direct("What did you find when you executed the warrant?", "\"Forty-one oxycodone pills in a cereal box in the kitchen, a digital scale, $1,100 in cash, and a notebook of names and numbers.\""), .direct("What was in the notebook?", "\"First names and numbers, with entries like, T colon three times thirty equals ninety dollars. That reads as a record of sales.\""), .direct("Who was home at the time of the search?", "\"{D} was inside with one other visitor. {DL} told us people stayed there on and off and that the kitchen was shared.\""), .direct("How do the quantities fit with personal use?", "\"Forty-one pills plus a scale and a ledger are more than personal use in my experience. The pills were split into bundles, and the notebook matched the prices.\""), .cross("Isn't it true the pills were in the kitchen, not the defendant's bedroom?", "\"Yes, in a cereal box on a kitchen shelf. It was a shared room, and anyone staying there could have put it there.\""), .cross("Did you find drugs or cash on the defendant's person?", "\"No. The cash was in a drawer and nothing was found on {DL}. That's one reason I can't say whose it was.\""), .cross("Was the defendant's handwriting confirmed in the ledger?", "\"A comparison suggested it matched some entries. I'd be careful, because a different guest may have written others, and I'm not a handwriting examiner.\""), .cross("Did you see the defendant sell anything during surveillance?", "\"No. We saw visits, not hand-to-hand exchanges. I can describe the traffic, but I can't say who inside was doing what.\""), .cross("Did other people live or stay at the trailer?", "\"Yes, at least two others came and went. {DL} named them and said they stayed there for a night or two at a time.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("How do you know {D}?", "\"I'm a neighbor, two trailers down. I've lived in the park for years, and I know {D} to wave at and talk to over the fence.\""), .direct("What have you seen at the defendant's trailer?", "\"Cars coming and going, and sometimes a few people hanging around outside. It's been busier than usual the last few months.\""), .direct("Who did you see staying there?", "\"A couple of people I'd seen before, who slept there some nights. {DF} told me they were friends with nowhere to go.\""), .direct("Did you ever complain about the traffic?", "\"I mentioned it to {D.him} once, and {D.he} said it was the friends staying over. I didn't call anyone about it myself.\""), .direct("What kind of person is the defendant?", "\"Quiet, helpful, and generous. {DF} has fixed my porch step and loaned me tools, and I've never seen {DF} act like a dealer.\""), .direct("Did the defendant ever seem to have a lot of money?", "\"No. {D.He} drives an old car and wears the same clothes. I'd say {D.he} struggles like the rest of us.\""), .cross("You can't see inside the trailer from your place, can you?", "\"No, I'm two trailers down. I can see the front yard and the road, but not what happens inside.\""), .cross("You noticed cars stopping for two minutes at all hours?", "\"I noticed lots of short stops, yes. I didn't time them, but it was frequent, and I'd say it was odd.\""), .cross("Did you ever see money change hands?", "\"No, I never saw anything change hands. I only saw cars come and go.\""), .cross("You didn't call the sheriff, though neighbors did?", "\"I didn't, because I didn't want to cause trouble. Others did, and I understand why they were worried.\""), .cross("You have no idea what was kept in the kitchen?", "\"None. I've never been inside {D.his} trailer, so I couldn't say what was in a cereal box.\"")],
        theory: ("{D} kept a trailer where pills were stored and sold.", "A host whose guests used the kitchen."),
        allocution: "\"I let the wrong people in, and I'm sorry. I took in friends who had nowhere to go, and I didn't look at what they kept in my kitchen. Those pills aren't mine, and I don't own a scale. I should have been stricter about who stayed, and I'm sorry for the neighbors' trouble.\"",
        truths: ("{DL}'s handwriting matched the ledger entries.", "The ledger belonged to a guest who left it in a drawer, and the handwriting is hers."),
        defendant: [.direct("Do you live alone at the trailer?", "\"No. I let people crash there when they've got nowhere to go. A couple of friends were staying that month, and I didn't ask many questions.\""), .direct("Whose pills and scale were those?", "\"Not mine. I don't take oxycodone and I don't own a scale. One of the people staying with me must have kept them in the kitchen.\""), .direct("Why did cars stop so often?", "\"I couldn't tell you for sure. People came to see my guests, and I figured it was friends. I didn't track who stopped when.\""), .direct("What about the notebook?", "\"It was in a drawer in the kitchen. A guest left it, and I never looked closely at what it was. The writing isn't how I write.\""), .direct("How did you react when deputies came?", "\"I let them in and told them people stayed there and that the kitchen was shared. I gave names, and I didn't resist.\""), .direct("What's your income?", "\"I get disability and do odd jobs. The cash was some of that, and I'd gotten paid a day earlier for helping someone move.\""), .cross("The trailer is in your name, isn't it?", "\"Yes, the trailer is mine and I pay the lot rent. Whatever goes on there is on my property, and I understand that.\""), .cross("You knew a lot of cars were stopping at all hours?", "\"I noticed some, and a neighbor said something once. I told myself it was my guests' friends, and I shouldn't have let it go.\""), .cross("The ledger entries match your handwriting in places, don't they?", "\"I was told that. I do write that way sometimes, and I may have jotted things for my guests, but I never kept a record of sales.\""), .cross("You had $1,100 in cash at home?", "\"I keep cash at home because I don't trust banks. I told the deputies it was my money and the amount was reasonable.\""), .cross("Forty-one pills were in your kitchen and you never saw them?", "\"I never looked in that cereal box. I don't eat cereal. I should have noticed, but I didn't.\"")],
        openings: ("After sixty days of neighbor complaints about two-minute visits at all hours, deputies searched {D}'s trailer with a warrant and found 41 oxycodone pills in a cereal box, a scale, $1,100 in cash, and a ledger with sale prices. The State will show this was a trailer where pills were stored and sold.", "{D} let friends sleep there, shared the kitchen with them, and never looked in a cereal box. The defense says the State found a crowded home with many hands, and nothing ties {DL} to the pills or the notebook."),
        closings: ("Forty-one pills, a scale, a ledger with prices, $1,100 in a drawer, and weeks of two-minute car visits all in one trailer that is {D}'s home. {D.He} was the one in control of the place, and the picture is unmistakable.", "The pills were in a shared kitchen, nothing was found on {D}, and the ledger may be a guest's notebook. A crowded trailer and a cereal box leave too much doubt about who kept what."),
        timeline: [(-60, "The first neighbor complaint."), (-14, "Surveillance begins."), (0, "Search warrant executed at the trailer.")],
        identified: "Neighbors' complaints and surveillance.",
        aggravating: ["The offense involved sale or delivery"],
        mitigating: ["The defendant has accepted responsibility", "The defendant has a support system in the community"],
        mood: .divided,
        doctrines: ["searchSeizure", "burdenOfProof"])

    static let atvTheft = SmallCases.make(
        key: "story.atvTheft",
        category: .property,
        headlines: ["Four-Wheeler Taken From Farm Shed, Found Repainted", "ATV Theft Linked to Teen Through Social Media Post"],
        law: "felonyLarceny",
        threshold: 6,
        spec: "Stole an all-terrain vehicle valued at $4,800 belonging to {V}, on {DATE}.",
        ages: 18...32,
        victim: true,
        summary: "{V}'s four-wheeler was taken from a farm shed on {DATE}. A week later, a photo posted on social media showed a green four-wheeler with {D} riding it. {V}'s was red. A deputy found the ATV in {DL}'s uncle's barn with fresh green spray paint over red and the VIN plate pried off. {DL} says {D.he} bought it for $800 from a stranger.",
        state: [E(.physical, 3, "The ATV", "A four-wheeler painted green over red with the VIN plate removed; the frame VIN matches {V}'s.", .search), E(.digital, 3, "Social Media Post", "{D} on the ATV with the caption 'new ride.'")],
        defense: [E(.statement, 2, "Purchase", "{DL} says {D.he} bought the ATV for $800 from a stranger.")],
        role: "Sheriff's property crimes detective",
        exam: [.direct("What was reported to you on {DATE}?", "\"{V} reported that a red four-wheeler was taken from a farm shed overnight. The shed lock had been cut and nothing else was missing.\""), .direct("How did {D} come to your attention?", "\"A week later a photo went up on social media showing a green four-wheeler with {D} riding it and the caption, new ride.\""), .direct("Why did that photo matter?", "\"{V}'s ATV was red, but the photo's frame and fenders matched. A tip led me to look at the ATV in a barn belonging to {DL}'s uncle.\""), .direct("What did you find in the barn?", "\"A four-wheeler with fresh green spray paint over red, and the VIN plate pried off. The frame VIN underneath matched {V}'s machine.\""), .direct("What did the defendant say about it?", "\"{D.He} said {D.he} bought it for $800 from a stranger and that the paint job was already on it when {D.he} bought it.\""), .direct("Did you find any paint or tools?", "\"I found a can of green paint, a brush, and a pry bar in the barn. I can't say who handled them.\""), .cross("Isn't it true you found the ATV in the uncle's barn, not the defendant's property?", "\"Yes, it was in the uncle's barn. The uncle told me {DL} had asked to store it there a few days before.\""), .cross("Did you see the defendant paint or move the ATV?", "\"No. I have the photo and the barn, but no witness who saw the painting or who took it from the shed.\""), .cross("Why would the defendant post a photo of a stolen ATV?", "\"I can't answer that. It's unusual for someone who knows a machine is stolen, and I can only report that {DL} posted it.\""), .cross("Was the defendant cooperative?", "\"Yes. {D.He} answered my questions, gave the story about the purchase, and didn't try to hide the machine.\""), .cross("Did you check the seller the defendant described?", "\"I asked for a name and a number, and {D.he} had neither. I can't say that person doesn't exist.\"")],
        defenseRole: "Defendant's uncle",
        defenseExam: [.direct("What is your relationship to {D}?", "\"{D} is my nephew. I've known {DF} all {D.his} life, and we've worked on projects around my farm for years.\""), .direct("How did the ATV get to your barn?", "\"{D.He} asked if {D.he} could keep it there for a while, since {D.he} lacks storage at home. I said yes.\""), .direct("What did the defendant say about where it came from?", "\"That {D.he} had bought it for $800 from a seller. {D.He} seemed proud of it and didn't seem to be hiding anything.\""), .direct("Did you notice anything about the paint?", "\"It was green and looked fresh. I figured {DF} had painted it or the seller had, and I didn't think about it any further.\""), .direct("What kind of person is the defendant?", "\"Honest as far as I've ever known. {D.He} has never been in trouble that I'm aware of, and I've trusted {D.him} with my tools.\""), .direct("What did you do when the deputy came?", "\"I let the deputy into the barn right away, showed where {DF}'s ATV sat, and told {DF} to come explain.\""), .cross("You didn't see the defendant buy it, did you?", "\"No, I wasn't there when any money changed hands. All I have is {D.his} word about the 00 and the seller.\""), .cross("Did you wonder why the defendant stored it in your barn?", "\"I did a little. {D.He} said it was just for space, and I didn't press. I wish I'd asked more.\""), .cross("Did you look at the VIN plate or paint?", "\"No, I never looked at the plate or the machine closely. It was just another four-wheeler in my barn.\""), .cross("Did the defendant bring the paint into your barn?", "\"There was paint in the barn, but I don't know whose it was or when it came. I keep a lot of supplies out there.\""), .cross("You'd want to protect your nephew, wouldn't you?", "\"Of course I care about {D.him}. But I'm telling the truth about what I saw, and I wouldn't lie to a court.\"")],
        theory: ("{D} stole an ATV, painted it, and posted a photo of himself riding it.", "A buyer who didn't think about the VIN."),
        allocution: "\"I should have asked a lot of questions about an eight-hundred-dollar four-wheeler. I was proud of it, and I rode it around in the open because I believed I'd bought it fair. I'm sorry to {V} for the loss, and I'll return it and do whatever the court asks.\"",
        truths: ("A neighbor's camera showed {DL}'s truck at {V}'s shed at 2 a.m.", "The man who sold {DL} the ATV was arrested for a string of ATV thefts."),
        defendant: [.direct("How did you get the four-wheeler?", "\"I bought it for $800 from someone I met through a friend. It was already green when I got it, and the price seemed fair.\""), .direct("Why did you post a photo of yourself on it?", "\"I was proud of the purchase. I had no reason to hide it because I believed I'd bought it fair and square.\""), .direct("Where did you keep it?", "\"At my uncle's barn. I don't have room at my place, and my uncle said I could use the space for a while.\""), .direct("Did you notice the missing VIN plate?", "\"I did, and I should have asked about it. The seller said it had been lost during repairs, and I took that at face value.\""), .direct("What did you do when the deputy came?", "\"I told the deputy everything I knew about how I got it. I showed the receipt I had, which was a note, and nothing else.\""), .direct("What do you want to say to {V}?", "\"I'm sorry for the loss, and I'd return it. I wouldn't have bought it if I had known.\""), .cross("You didn't get a bill of sale or a title, did you?", "\"No. It was a cash deal and a handshake. I know that was careless and I'll own it.\""), .cross("The VIN plate had been pried off, correct?", "\"I was told so. I noticed it was missing, but I didn't think about pry marks or what they meant.\""), .cross("Your truck was seen at {V}'s shed at 2 a.m., wasn't it?", "\"I'm told a neighbor's camera shows a truck like mine. I don't remember being there, and I can't explain it.\""), .cross("Did you know the ATV had been repainted?", "\"I knew it was green. I didn't know it had been red, and I didn't ask who painted it.\""), .cross("You can't name the seller, can you?", "\"No. I only have a first name and a phone number that no longer works. I know that makes my explanation hard to believe.\"")],
        openings: ("A week after {V}'s red four-wheeler vanished from a farm shed, {D} posted a photo riding a green one with the caption, new ride. A deputy found it in the uncle's barn with fresh green paint over red and the VIN plate pried off, and the frame VIN matched {V}'s.", "{D} paid $800 to a stranger, posted the ATV online for the world to see, and stored it in a relative's barn. The defense says a thief does not do that, and the State cannot show {DL} knew it was stolen."),
        closings: ("Fresh green paint over red, a pried-off VIN plate, and a frame number that matches {V}'s. {D} paid $800 for a machine with no title, no paper, and no seller's name, and a neighbor's camera places {DL}'s truck at the shed.", "{D} posted the ATV publicly, stored it in the open, and told the deputy everything. Buying from an unknown seller is carelessness, and a person who thought they bought a used machine lacks the knowledge the charge demands."),
        timeline: [(0, "2 a.m.: the ATV leaves the shed."), (5, "{DL} posts the photo."), (7, "A deputy finds the ATV in the barn.")],
        identified: "A social media post and a deputy's tip.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mitigating: ["The defendant has accepted responsibility"],
        impact: "That four-wheeler was my work vehicle on the farm, and I couldn't move feed or check fence lines without it. I found the shed door open and the tracks leading out to the road. I had to borrow a neighbor's machine for a week. Then I saw it posted online, painted green.",
        genders: ["D": .male])

    static let deputyShove = SmallCases.make(
        key: "story.deputyShove",
        category: .violent,
        headlines: ["Man Shoved Deputy During Traffic Stop", "Assault on Law Enforcement Charge After Pat-Down"],
        law: "assaultLEO",
        threshold: 6,
        spec: "Assaulted {V}, a sworn law enforcement officer, inflicting physical injury, while {V.he} was discharging official duties, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "A deputy stopped {D} for a revoked tag on {DATE} and asked {D.him} to step out for a pat-down after smelling marijuana. {DL} shoved the deputy in the chest and ran. The deputy fell against the car and sprained a wrist. {D.He} was caught after a short chase. {DL} says {D.he} flinched when touched and didn't mean to shove.",
        state: [E(.video, 3, "Body Camera", "{D} shoves the deputy with both hands and runs."), E(.document, 2, "Deputy's Medical Note", "A sprained wrist and a bruised hip.")],
        defense: [E(.statement, 1, "Flinch", "{DL} says {D.he} flinched when the deputy touched {D.his} waist.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you stop {D} for?", "\"A revoked registration tag on {D}'s vehicle on the evening of {DATE}. It was a routine stop, and I made it in the lot of a shopping center.\""), .direct("Why did you ask the defendant to step out?", "\"I smelled marijuana coming from the vehicle. I asked {D.him} to step out so I could pat {D.him} down for weapons before searching.\""), .direct("What happened next?", "\"{D.He} stepped out, I put a hand on {D.his} waist to start the pat-down, and {D.he} shoved me hard in the chest with both hands.\""), .direct("How were you hurt?", "\"I fell backward against the patrol car and landed on my wrist and hip. The wrist was sprained and the hip bruised, and I couldn't grip properly for days.\""), .direct("What did the defendant do after the shove?", "\"{DL} ran. I called it out on the radio and chased on foot for about two blocks until other deputies helped catch {DL}.\""), .direct("Did you have a body camera on?", "\"Yes. It recorded the stop, the request to step out, the shove, and the foot chase. I've reviewed it for this case.\""), .cross("Isn't it true the defendant said, don't touch me, twice?", "\"Yes, the video has those words twice before the shove. I should be clear that I hadn't touched {DL} yet on the first one.\""), .cross("Did you tell the defendant why you wanted to pat down?", "\"I said I smelled marijuana and wanted to check for weapons. I explained it, but I don't think I gave a long speech.\""), .cross("Did the defendant strike you with a fist?", "\"No. It was an open-hand push with both hands to my chest. {D.He} didn't punch or kick me.\""), .cross("Was the defendant cooperative until that moment?", "\"Yes. {D.He} handed over documents, answered questions, and got out of the car when asked. The shove was the first sign of resistance.\""), .cross("Did you find marijuana?", "\"Yes. After the chase, we found a bag of marijuana in {DL}'s sock. That was the reason {DL} might have reacted.\"")],
        defenseRole: "Passenger",
        defenseExam: [.direct("How do you know {D}?", "\"I was a passenger in {D}'s car that evening. We were on our way to dinner when the deputy pulled us over.\""), .direct("What did you see during the stop?", "\"The deputy came to the window, asked for papers, and then asked {DF} to step out. {DF} got out calmly at first.\""), .direct("What did you hear the defendant say?", "\"{D.He} said, don't touch me, twice, in a nervous voice. It sounded more scared than angry.\""), .direct("What did you see the defendant do?", "\"When the deputy put a hand at {DF}'s waist, {DF} jumped and threw both hands up. The deputy stumbled back and {DF} took off.\""), .direct("How does the defendant usually react to being touched?", "\"{DF} startles easily. I've seen {DF} jump when someone tapped a shoulder from behind. It's a reflex.\""), .direct("What did you do?", "\"I stayed in the car as told. I called out to {D.him} to stop, but {D.he} kept going.\""), .cross("You didn't see exactly what happened between their hands, did you?", "\"I was in the passenger seat, looking over my shoulder. It happened quickly, and I can't give a frame-by-frame account.\""), .cross("You saw the defendant run away?", "\"Yes, I did. {DF} ran from the deputy and the deputy chased. I know that looks bad.\""), .cross("You agree the defendant pushed the deputy?", "\"I saw the deputy go back. Whether it was a push or a flinch is how I saw it, and I can't read {D.his} mind.\""), .cross("Did you smell marijuana in the car?", "\"I smelled something faintly. I don't know where it came from, and I didn't see {DF} smoke.\""), .cross("You're a friend of the defendant's, aren't you?", "\"Yes, a good friend. I want to be truthful, and I'm telling you what I saw as best I remember.\"")],
        theory: ("{D} shoved a deputy and ran.", "A flinch and a panic."),
        allocution: "\"I panicked when the deputy touched me, and my hands came up. I've always been jumpy about being touched without warning, and I told {V.him} twice to let me know first. I never meant to push anyone, and I certainly didn't mean to hurt {V.him}. I shouldn't have run.\"",
        truths: ("{DL} had a bag of marijuana in his sock.", "The body camera showed {DL} saying 'don't touch me' twice before the shove."),
        defendant: [.direct("What happened when the deputy put a hand on you?", "\"I flinched. I jumped when the deputy touched my waist, and my hands came up. I didn't mean to push anybody.\""), .direct("Why did you flinch?", "\"I've always been jumpy about being touched without warning. I'd told the deputy not to touch me twice because I was nervous.\""), .direct("Why did you run?", "\"I panicked. I knew I had a little marijuana on me, and I was scared of being arrested. It was a terrible decision.\""), .direct("Did you mean to hurt the deputy?", "\"No. I'd never hit anyone. When I saw the deputy fall, I felt sick, but I was already running, and I kept going.\""), .direct("What did you do when you were caught?", "\"I stopped and put my hands up. I didn't fight, and I told the deputies I was sorry about the push.\""), .direct("What would you say about that night now?", "\"It was my fault. I shouldn't have run and I shouldn't have been carrying. I'd apologize to the deputy in person.\""), .cross("You pushed with both hands, didn't you?", "\"Both hands came up. I call it a flinch, but I know the video looks like a shove.\""), .cross("The deputy fell and was injured, correct?", "\"I'm told that. I saw the deputy hit the car, and I'm sorry for it. I never wanted anyone hurt.\""), .cross("You said, don't touch me, twice before it happened?", "\"I did. That's a sign I was already worried, and I wish I'd just cooperated and let the deputy finish.\""), .cross("You had marijuana in your sock?", "\"Yes. That's why I was nervous. I figured the pat-down would find it.\""), .cross("You ran two blocks?", "\"I did. I ran because I was afraid, and I didn't think about the consequences. I made it worse.\"")],
        openings: ("At a traffic stop for a revoked tag, a deputy smelled marijuana and moved to pat {D} down, and {DL} shoved the deputy in the chest with both hands and ran. The deputy hit the patrol car, sprained a wrist, and bruised a hip, and the body camera captured it all.", "{D} said, don't touch me, twice, and flinched when a hand touched {D.his} waist. The defense says a startle reflex is not an intentional assault, and the State cannot prove otherwise."),
        closings: ("Both hands, a hard shove, a deputy against the car, and a run for two blocks. The video shows the push and the injury, and the bag of marijuana in {D}'s sock explains why.", "{D} warned the deputy twice and startled when touched, and then ran in panic. A flinch and a bad decision are not the same as an intentional assault on an officer."),
        timeline: [(0, "Evening: the stop for a revoked tag."), (0, "The pat-down request and the shove."), (0, "Two blocks later, deputies catch {DL}.")],
        identified: "The deputy's body camera.",
        aggravating: ["The victim was a law enforcement officer performing official duties"],
        mitigating: ["The defendant has accepted responsibility"],
        impact: "My wrist took six weeks to heal, and I couldn't write reports or hold my service weapon without pain. I stopped a car for a tag violation, which I do a dozen times a week. I fell against the door and felt it give. I'd rather not be hurt doing a routine stop.",
        genders: ["D": .male])

    static let pistolFromTruck = SmallCases.make(
        key: "story.pistolFromTruck",
        category: .property,
        headlines: ["Handgun Stolen From Unlocked Truck Turns Up at Traffic Stop", "Man Says He Found Pistol in a Field"],
        law: "larcenyFirearm",
        threshold: 6,
        spec: "Stole a firearm, a 9mm pistol, belonging to {V}, from a vehicle, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "{V}'s 9mm pistol was taken from the glove box of an unlocked truck on {DATE}. Two weeks later a deputy stopped {D} for a stop sign and found the pistol under the driver's seat. The serial number matched. {DL} says {D.he} found it in a field and was bringing it to the sheriff's office.",
        state: [E(.physical, 3, "The Pistol", "{V}'s 9mm with the serial number matching, loaded, under {D}'s seat.", .search), E(.document, 2, "Report", "{V} reported the pistol stolen two weeks earlier.")],
        defense: [E(.statement, 1, "Found Gun", "{DL} says {D.he} found the gun in a field.")],
        role: "Sheriff's deputy",
        exam: [.direct("Where did you find the pistol?", "\"Under the driver's seat of {D}'s car during a stop for a stop sign. It was loaded, and the serial number matched {V}'s stolen 9mm.\""), .direct("What did {D} say about it?", "\"{D.He} said it was found in a field and that {D.he} was planning to bring it to the sheriff's office.\""), .direct("Did the defendant ever contact the sheriff's office?", "\"No. We had no call or visit from {D.him} in the two weeks between the theft and the stop.\""), .direct("How did you come to stop the defendant's car?", "\"I saw it roll through a stop sign at a quiet intersection and turned on my lights. {D.He} pulled over right away and was polite with me.\""), .direct("What did you see when you looked into the car?", "\"Nothing at first. When I asked {DL} to step out, I saw the grip of a pistol sticking out from under the driver's seat.\""), .direct("How did you trace the pistol to {V}?", "\"I ran the serial number through dispatch and it came back to a theft report from two weeks earlier. {V} had reported a 9mm taken from an unlocked truck.\""), .cross("{D} told you the plan was to hand it in. Why do you doubt that?", "\"I do not know what was in {D.his} mind. The car was headed away from the sheriff's office, and two weeks had already passed.\""), .cross("{D} was cooperative, wasn't {D.he}?", "\"Yes. {D.He} told me where the gun was as soon as I asked and did not resist.\""), .cross("Did you see anything tying the defendant to {V}'s truck?", "\"No. I found no evidence that {DL} was at the truck, only that the pistol ended up in {DL}'s car.\""), .cross("Did you check whether the pistol had been fired or tampered with?", "\"The pistol was loaded and in working condition. I did not do any further testing on it for fingerprints.\""), .cross("Was there any camera footage placing the defendant on {V}'s street the night of the theft?", "\"Not that I reviewed. I can't tell the jury {DL} was ever near that truck.\"")],
        defenseRole: "Defendant's brother",
        defenseExam: [.direct("Did {D} mention finding a gun?", "\"Yes, a few days earlier. {D} told me about finding something in a field.\""), .direct("What did the defendant say about it?", "\"{D.He} said it was a pistol and did not know whose it was. {D.He} seemed unsure what to do.\""), .direct("What is your relationship to the defendant?", "\"I'm {D.his} sibling. We talk or text almost every day.\""), .direct("When did the defendant tell you about the pistol?", "\"Within a day or two of finding it. {D.He} said it was lying in a field and asked what to do.\""), .direct("What did you advise?", "\"I told {D.him} to take it straight to the sheriff's office and not to keep it in the car. {D.He} agreed.\""), .direct("What did you tell the defendant to do with the gun after hearing about it?", "\"I told {D.him} to take it straight to the sheriff's office and not carry it around. I said that more than once, because a loose gun in a car worries me.\""), .cross("Did you see the gun yourself?", "\"No. I never saw it, only heard about it.\""), .cross("Did the defendant turn it in before the stop?", "\"Not that I know of. It was still in the car when the deputy found it.\""), .cross("How long between the defendant telling you and the stop?", "\"A few days. I did not check on it, and I wish I had.\""), .cross("Did you ever see the pistol or check that it was turned in?", "\"No. I only heard about it from {D.him}, and I did not follow up after that first conversation.\""), .cross("Did the defendant ever mention anything about a truck or {V}?", "\"No. {DF} never said anything about a truck and never mentioned anyone's name.\"")],
        theory: ("{D} took a pistol from a truck and kept it.", "A finder who didn't know whose it was."),
        allocution: "\"I should have turned that pistol in the day I found it. I found it lying in the grass along my road to work, and I was going to take it to the sheriff's office but I kept putting it off. I never touched anyone's truck. I'm sorry for the worry I caused the owner.\"",
        truths: ("A neighbor's camera showed {DL}'s car on {V}'s street the night of the theft.", "The field was on {D.his} route to work, and the gun had been dropped by a thief."),
        defendant: [.direct("Did you take the pistol from the truck?", "\"No. I did not touch anyone's truck. I found the pistol later in a field.\""), .direct("Where exactly did you find it?", "\"In a field along the road I take to work. It was lying in the grass, and I picked it up because I was worried about a child finding it.\""), .direct("Why did you keep it in your car?", "\"I was scared of it, and I did not know who to call. I put it under the seat and meant to take it in.\""), .direct("Tell the jury what you were doing the morning you found the pistol.", "\"I was driving to work along my usual back road. I stopped because something shiny was lying in the weeds at the edge of a field.\""), .direct("What did you do when you saw it was a gun?", "\"I picked it up carefully, saw that it was loaded, and put it under the seat. I wasn't sure what to do and I didn't want to leave it for a child to find.\""), .direct("What did you plan to do with it?", "\"Take it to the sheriff's office. I told my sibling I'd do it that weekend, and I put it off because of work.\""), .cross("You kept a loaded gun for two weeks. Why not call the sheriff?", "\"I know I should have. I was afraid I would be blamed, and I kept putting it off. That was a bad choice.\""), .cross("The pistol was loaded when found. Did you load it?", "\"No. It was loaded when I found it. I never touched the rounds.\""), .cross("Why was the car not headed to the sheriff's office when you were stopped?", "\"I was headed to run errands first. I planned to go that afternoon. I can see how that sounds.\""), .cross("A neighbor's camera showed your car on {V}'s street the night of the theft, didn't it?", "\"That is what the camera shows. I drive through that part of town to visit a friend, and I did not stop near any truck.\""), .cross("The stop sign is not the first time a deputy might have found it. Why was it still in your car?", "\"Because I hadn't gone to the sheriff's office yet. That's my fault, and I told the deputy the truth as soon as I was asked.\"")],
        openings: ("{V}'s 9mm pistol was taken from the glove box of an unlocked truck. Two weeks later, a deputy found that same pistol, loaded, under the driver's seat of {D}'s car.", "{D} found a pistol in a field and did not know whose it was. The defense will show someone who was scared, told a friend, and was on the way to turn it in."),
        closings: ("Same pistol, same serial number, and two weeks of silence. A person who finds a loaded gun and keeps it hidden under the seat is not planning to return it.", "{D} told the truth the moment the deputy asked and told others about the find. Waiting too long is poor judgment, but no one has shown that {D.he} took this gun from that truck."),
        timeline: [(0, "Overnight: the pistol leaves the glove box."), (14, "A deputy stops {DL} for a stop sign."), (14, "The pistol is found and traced.")],
        identified: "A traffic stop and a serial number.",
        aggravating: ["The offense involved a firearm"],
        mitigating: ["The defendant has accepted responsibility"],
        impact: "I keep my gun at home in a lockbox now, but I used to leave it in the glove box on the way to work. I came out one morning to find the door open and the box empty. I worried every day about who had it and what they might do. That's a hard thing to carry.",
        genders: ["D": .male])

    static let trafficCocaineMotel = SmallCases.make(
        key: "story.trafficCocaineMotel",
        category: .drugs,
        headlines: ["Motel Room Search Finds Cocaine, Cash, and a Scale", "Guest Says Bag Belonged to Visitor"],
        law: "traffickingCocaine",
        threshold: 7,
        spec: "Possessed 31 grams of cocaine, a Schedule II controlled substance, on {DATE}.",
        ages: 24...50,
        victim: false,
        summary: "A motel manager called deputies about heavy traffic in room 114 on {DATE}. {D} had rented the room under {D.his} own name. Deputies found a bag with 31 grams of cocaine, a digital scale, and $2,300 in the bathroom. {DL} says {D.he} rented the room for a friend and never looked in the bag.",
        state: [E(.physical, 3, "The Cocaine", "31 grams of cocaine in a plastic bag, with a scale and $2,300.", .search), E(.document, 2, "Motel Registration", "Room 114 rented in {D}'s name for six nights.")],
        defense: [E(.statement, 2, "Friend", "{DL} says {D.he} rented the room for a friend who paid cash.")],
        role: "Sheriff's narcotics detective",
        exam: [.direct("What prompted you to investigate room 114?", "\"The motel manager reported heavy traffic to that room. We counted about thirty visitors in six days, which is more than a normal guest has.\""), .direct("What did you find when you searched?", "\"In the bathroom, a bag with 31 grams of cocaine, a digital scale, and $2,300 in cash. The quantity and the scale suggest distribution.\""), .direct("Who rented the room?", "\"{D}, under {D.his} own name. The motel records show {D.his} name and card on the booking.\""), .direct("How did the investigation begin?", "\"The motel manager called to report heavy foot traffic to room 114. We put the room under observation for about a day and counted visitors.\""), .direct("What did you observe from the parking lot?", "\"People walked up, knocked, stayed a few minutes, and left. I counted roughly thirty visits in six days, with most staying under ten minutes.\""), .direct("What did the warrant search recover?", "\"In the bathroom, behind a panel above the tub, we found a bag with 31 grams of cocaine, a digital scale, and $2,300 in small bills.\""), .cross("{D} says the room was rented for a friend, doesn't {D.he}?", "\"Yes, that is the explanation I got. I can't rule it out, and I did not locate the friend.\""), .cross("Were fingerprints found on the bag?", "\"None that were usable. We did not tie the bag to anyone by prints.\""), .cross("Did you see the defendant inside the room during the visits?", "\"No. The manager saw the traffic, but I did not personally see who was inside at any given time.\""), .cross("Did you see the defendant at the motel while you were watching?", "\"Not on the days I watched. I cannot say {D.he} was present for most of the visits.\""), .cross("Did you find any messages or notes in the room tying the defendant to the bag?", "\"No. The room held clothes, snacks, and a phone charger, and nothing tied the bag to {DL} directly.\"")],
        defenseRole: "Motel manager",
        defenseExam: [.direct("Did {D} stay in the room?", "\"On some nights, yes. {D} stayed some nights and other times the room had different people in it.\""), .direct("Who else came and went?", "\"Different people each day. I did not know them. I just saw guests arriving and leaving in a steady stream.\""), .direct("Why did you call deputies?", "\"The traffic was heavier than I had ever seen for one room. I was worried about what was going on.\""), .direct("What is your job at the motel, and how long have you done it?", "\"I'm the manager and have been for eleven years. I handle check-in, housekeeping, and any complaints.\""), .direct("What did you notice about room 114?", "\"Visitors came and went all day. Cars pulled up for a few minutes and left, which is not the usual pattern for a room.\""), .direct("Who did you see at the front desk when the room was booked?", "\"{DF}, who paid with a card in {D.his} name and said it was for a friend. {DF} was polite and did not give me any trouble.\""), .cross("Did you ever see the defendant with drugs?", "\"No. I only saw the visitors.\""), .cross("Did the defendant pay for the room in {D.his} own name?", "\"Yes, with a card in {D.his} name. {D.He} did not hide who was renting it.\""), .cross("Did the defendant seem nervous about the visitors?", "\"No. {D.He} seemed normal to me. I never had a problem with {D.him} at the desk.\""), .cross("Did you ever go into the room while it was rented?", "\"Only for a housekeeping check on the second day. I did not go into the bathroom or look behind any panel.\""), .cross("Did you see the defendant meeting visitors?", "\"No. I saw the visitors, but I rarely saw {DF}, and I can't connect {DF} to any of them.\"")],
        theory: ("{D} rented a room and stored cocaine and cash in it.", "A man who rented a room for a friend."),
        allocution: "\"I let the wrong person use my name, and I'm sorry. I rented that room as a favor for a friend, and I never opened his bag. I didn't know what was in it. I have a job and a family, and I should have asked more before I put my name on anything.\"",
        truths: ("{DL}'s phone held a message that said 'the product's in the bathroom.'", "The friend later admitted the bag was his and pleaded guilty."),
        defendant: [.direct("Whose bag was in the bathroom?", "\"It was my friend's. I rented the room for my friend and I did not know what the bag held.\""), .direct("Did you look inside the bag?", "\"No. I never opened it. I did not see any cocaine and I did not know it was in there.\""), .direct("Why was your name on the room?", "\"I paid with my own card as a favor to my friend. I did not think it mattered whose name was on it.\""), .direct("Tell the jury why you rented a motel room.", "\"A friend needed a place to stay for a few days and didn't have a credit card. I paid with mine as a favor and the friend gave me cash.\""), .direct("How many nights did you stay there?", "\"Two or three. I slept there when I was between shifts, and mostly it was my friend's room.\""), .direct("What was your friend doing at the motel?", "\"Working on something. I didn't ask, and I didn't want to know, because I only wanted to help.\""), .cross("You stayed in the room six nights. You never saw the bag?", "\"I stayed a few of those nights. I saw it, but I did not look inside, because it was not mine.\""), .cross("About thirty people came to your room in six days. Didn't that strike you as odd?", "\"I was not there for most of it. When I was, there were visitors, and I did not ask questions.\""), .cross("A scale and $2,300 in the bathroom. And you want us to believe you knew nothing?", "\"I knew nothing about it. I did not go into the bathroom bag. I know it looks bad, but that is the truth.\""), .cross("Thirty visitors in six days. What did you think was going on?", "\"I thought my friend had a lot of acquaintances. I wasn't there most of the time and didn't think about it.\""), .cross("You never went into the bathroom for six nights and never saw a bag?", "\"I used the bathroom, but the panel was closed and I wasn't looking around. If I had seen it, I would have called someone.\"")],
        openings: ("A motel manager called about heavy traffic in room 114. When deputies searched it, they found 31 grams of cocaine, a digital scale, and $2,300 in the bathroom, in a room rented in {D}'s name.", "{D} rented the room as a favor and never looked in the bag. The defense will show that no fingerprints tie {DL} to the cocaine and that visitors came and went when {D.he} was away."),
        closings: ("Thirty visitors in six days, a scale, cash, and cocaine, all in a room that {D} rented and paid for. That is not a coincidence, and it is not a friend's problem alone.", "A name on a registration is not a name on a bag. No usable fingerprints, no sighting of {D} with drugs, and a motel full of different guests. The State has not proved knowing possession."),
        timeline: [(-6, "{DL} rents room 114."), (0, "The manager calls deputies."), (0, "Deputies search the room with a warrant.")],
